/* A118 staged author data; promote only after manifest and registry checks. */
(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('rook','Rook has separate histories: the bird name is Old English hrōc, the chess piece comes from Persian rukh (“chariot”), and the verb meaning cheat has an uncertain origin.',[C('rook.s1','秃鼻乌鸦','A rook returned to the colony at dusk, carrying a twig to repair its nest in the old oak.','黄昏时，一只秃鼻乌鸦叼着树枝回到群落，修补老橡树上的巢。','A rook returned to the colony / carrying a twig / to repair its nest.','rook.s1 指成群筑巢的欧亚鸦科鸟类。','乌鸦回巢并带着树枝修巢。'),C('rook.s2','（国际象棋）车','The white rook moved six squares along the open file and captured the opponent’s bishop.','白方车沿着空列移动六格，吃掉了对方的象。','The white rook moved along the file / and captured / the bishop.','rook.s2 指国际象棋中沿横线或竖线移动的棋子。','棋子沿直线移动并吃子。'),C('rook.s3','欺骗；敲诈','The dishonest mechanic tried to rook the tourist by charging her twice for the same repair.','不诚实的修车工试图欺骗游客，对同一项维修重复收费。','The mechanic tried to rook the tourist / by charging twice / for one repair.','rook.s3 作动词，指欺骗或多收费。','修车工对同一项服务重复收费。')],M('The mechanic rooked the tourist by charging the exact agreed price and giving her a full refund.','The mechanic rooked the tourist by charging twice for the same repair.','按约收费并退款不是欺骗或敲诈。','meaning'),[q('Where did the rook return at dusk?','to its nesting colony in an oak','to the chessboard’s open file','to the repair shop counter','鸟儿黄昏时回到了橡树上的巢群。',1,'context'),q('How did the white rook move?','six squares along an open file','diagonally across one corner only','in a circle around the bishop','国际象棋车沿空列移动并吃掉对方的象。',2,'context'),q('What did the mechanic do when he tried to rook the tourist?','charged twice for the same repair','repaired a rook’s nest','moved a chess piece six squares','修车工通过重复收费试图欺骗游客。',3,'context'),q('Which sentence uses rook as the chess piece?','The rook moved along a rank and captured a piece.','A rook carried a twig to its colony.','The shop tried to rook a visitor.','第一句的 rook 是国际象棋中的车。',1,'meaning')]);
P('room','Room comes from Old English rūm, “space”; it can mean a separated part of a building or empty space/opportunity for something.',[C('room.s1','房间','The nurse closed the room door so the sleeping patient would not hear the hallway conversation.','护士关上房门，以免熟睡的病人听到走廊里的谈话。','The nurse closed the room door / so the sleeping patient / would not hear the hallway.','room.s1 指建筑物中由墙壁分隔出的空间。','病人在房间内休息。'),C('room.s2','空间；余地','There is room for one more chair beside the window if we move the small table.','如果把小桌子挪开，窗边还能放下一把椅子。','There is room for one more chair / beside the window / if the table moves.','room.s2 指可容纳人或物的空余空间，也可指机会或余地。','挪开桌子后空出位置。')],M('There was room for another chair even though every part of the floor was already packed with furniture.','There was room for another chair because the table could be moved and the corner was empty.','地面已经塞满且没有空位时，不能说还有空间。','meaning'),[q('Why did the nurse close the room door?','to keep hallway talk from waking the patient','to give the patient a chess rook','to make room for a rooster','护士关门是为了不让走廊谈话吵醒病人。',1,'context'),q('What can fit beside the window?','one more chair','a whole dormitory','a flock of rooks','挪开桌子后，窗边还可以放一把椅子。',2,'context'),q('What does room mean in “a room in the building”?','a separated part of a building','empty space for another chair','an opportunity to cheat','此处 room 指建筑物中由墙壁隔开的房间。',1,'meaning'),q('What does “room for one more chair” mean?','enough empty space to fit it','a separate bedroom for it','permission to overcharge','room for a chair 指有足够空间放下椅子。',2,'meaning')]);
P('roommate','Roommate combines room and mate; it means someone sharing a rented flat or house, and in student use, someone sharing a dormitory room.',[C('roommate.s1','合住的室友','My roommate and I split the rent and take turns cooking in our shared apartment.','我和室友分摊房租，并轮流在合住的公寓里做饭。','My roommate and I split the rent / and take turns / cooking in our shared apartment.','roommate.s1 指与他人合租公寓或房屋的人。','两人共同租住并分担房租。'),C('roommate.s2','同寝室友','During her first semester, Nina’s roommate in the university dorm helped her find the campus library.','第一个学期里，妮娜的大学宿舍室友帮她找到了校园图书馆。','Nina’s roommate in the dorm / helped her find / the campus library.','roommate.s2 指住在同一间学生宿舍的人。','学生与室友共住一间宿舍。')],M('My roommate and I shared an apartment, but I paid all the rent and never lived with the other person.','My roommate and I shared the apartment and divided the rent between us.','从未同住或分担住房，不符合 roommate 的合住关系。','meaning'),[q('What do the apartment roommates share?','rent and cooking duties','a chess tournament','a separate room in different buildings','室友共同分摊房租并轮流做饭。',1,'context'),q('Where did Nina’s roommate live with her?','in the same university dorm room','in a separate city apartment','in the campus library','妮娜与室友住在同一间大学宿舍。',2,'context'),q('What does roommate mean in the apartment example?','someone sharing a rented home','someone sharing a chess piece','someone who works in a hospital room','roommate 指与自己共同租住的人。',1,'meaning'),q('What does roommate mean in the dormitory example?','a student who shares a dorm room','a landlord who collects rent','a nurse who closes a patient’s room','宿舍语境中的 roommate 指同寝室友。',2,'meaning')]);
P('rooms','Rooms is the plural of room, from Old English rūm, “space”; it refers to separate enclosed spaces in a building.',C('rooms.s1','房间；居室（复数）','The hotel has six rooms on the ground floor, each with a window facing the garden.','这家酒店一楼有六间客房，每间的窗户都朝向花园。','The hotel has six rooms / on the ground floor / each facing the garden.','rooms 是 room 的复数，指建筑物中的多个独立房间。','一楼的多个客房都朝向花园。'),M('The hotel has six rooms on the ground floor, but none has walls, a floor, or a ceiling.','The hotel has six separate rooms on the ground floor, each enclosed by walls.','没有墙面等围合空间的地方不能称为房间。','meaning'),[q('How many rooms are on the ground floor?','six','one','twelve','酒店一楼有六间客房。',1,'context'),q('Which direction do the rooms’ windows face?','toward the garden','toward the chessboard','toward the kitchen’s stove','每间客房的窗户都朝向花园。',1,'context'),q('What does rooms name?','separate enclosed spaces in a building','people who share a rented house','empty space for one more chair','rooms 指建筑物里的多个独立房间。',1,'meaning'),q('What is the singular form of rooms?','room','roost','roster','rooms 的单数形式是 room。',1,'word-formation')]);
P('roomy','Roomy combines room and -y; it describes a place large enough to hold people or things without crowding.',C('roomy.s1','宽敞的','The roomy minivan carried four suitcases and six passengers without anyone feeling cramped.','这辆宽敞的厢式车载着六名乘客和四个行李箱，没人觉得拥挤。','The roomy minivan carried suitcases and passengers / without anyone / feeling cramped.','roomy 指空间足够、不会显得拥挤。','车内能舒适容纳乘客和行李。'),M('The minivan was roomy because six passengers and four suitcases could not fit inside without being crushed.','The minivan was roomy because it held all six passengers and four suitcases comfortably.','无法容纳乘客和行李说明空间不足，不是宽敞。','meaning'),[q('How many passengers did the roomy minivan carry?','six','four','ten','宽敞的厢式车载着六名乘客。',1,'context'),q('How did passengers feel inside?','not cramped','crushed against every suitcase','unable to enter the vehicle','乘客和行李都能放下，因此车内不拥挤。',1,'context'),q('What does roomy mean?','large enough to hold people or things comfortably','empty of all people and furniture','designed for a chess match','roomy 指空间宽敞、可舒适容纳人或物。',1,'meaning'),q('Which suffix helps form roomy from room?','-y','-less','-er','room 加 -y 构成形容词 roomy。',1,'word-formation')]);
P('roost','Roost is an old English noun for a bird’s resting place; as a verb it means rest or sleep in a particular place.',[C('roost.s1','栖木；栖处','The hens climbed onto the wooden roost inside the coop as the sky grew dark.','天色渐暗时，母鸡爬上鸡舍里的木栖架。','The hens climbed onto the wooden roost / as the sky / grew dark.','roost.s1 作名词，指鸟类夜间休息或睡觉的地方。','母鸡在栖架上过夜。'),C('roost.s2','栖息；进窝','Every evening, the starlings roost in the tall trees beside the old station.','每天傍晚，椋鸟都在老车站旁的高树上栖息。','The starlings roost in tall trees / beside the old station / every evening.','roost.s2 作动词，指鸟类在某处休息或睡觉。','椋鸟每天傍晚在树上过夜。')],M('The hens used the roost by flying away at night and never resting on its wooden bars.','The hens used the roost by settling on its wooden bars to sleep.','夜间离开且从不休息在木架上，不符合栖息处的含义。','meaning'),[q('Where did the hens settle when it grew dark?','on the wooden roost','in the hotel’s guest rooms','on a chess rank','天色渐暗时，母鸡爬上木栖架。',1,'context'),q('Where do the starlings roost each evening?','in tall trees near the station','on the minivan roof','inside the hospital room','椋鸟每天傍晚在车站旁的高树上栖息。',2,'context'),q('What does roost mean as a noun?','a place where a bird rests or sleeps','a bird’s act of flying south','a roomy place for passengers','roost 作名词指鸟的栖息处。',1,'meaning'),q('What does roost mean as a verb?','rest or sleep in a particular place','build a room for a roommate','move a chess piece along a file','动词 roost 指在某处休息或睡觉。',2,'meaning')]);
P('rooster','Rooster is an American English word for an adult male chicken, formed from roost with the agent suffix -er.',C('rooster.s1','公鸡；雄鸡','The rooster crowed before sunrise, waking the farm workers in the nearby cottage.','公鸡在日出前打鸣，叫醒了附近小屋里的农场工人。','The rooster crowed before sunrise / waking the workers / in the cottage.','rooster 指成年雄鸡。','公鸡在清晨打鸣。'),M('The rooster laid a clutch of eggs and cared for the chicks as their mother.','The rooster crowed at dawn while the hens laid eggs in the coop.','产卵是母鸡的特征，不是公鸡的特征。','meaning'),[q('When did the rooster crow?','before sunrise','at noon after lunch','after the farm workers left','公鸡在日出前打鸣。',1,'context'),q('What kind of animal is a rooster?','an adult male chicken','a female bird that lays eggs','a chess piece that moves diagonally','rooster 指成年雄鸡。',1,'meaning'),q('Who woke the farm workers?','the crowing rooster','a roomy minivan','the hotel’s roommate','农场工人被打鸣的公鸡叫醒。',1,'context'),q('Which suffix appears in rooster?','-er','-less','-ish','roost 加 -er 构成 rooster。',1,'word-formation')]);
P('root','Root comes from Old English rōt, probably reinforced by Old Norse rót; it can name a plant part or a cause, and as a verb can mean grow roots, search, or cheer for a team.',[C('root.s1','根','The young oak’s root reached deep into the soil to draw water during the dry summer.','干燥的夏季里，小橡树的根深入土壤吸收水分。','The oak’s root reached into the soil / to draw water / during the dry summer.','root.s1 指植物在地下生长、吸收水分和养分的部分。','树根向土壤深处生长。'),C('root.s2','根源；起源','The investigator traced the root of the billing error to a duplicated entry in the old database.','调查人员发现账单错误的根源是旧数据库里一条重复记录。','The investigator traced the root of the error / to a duplicated entry / in the database.','root.s2 指问题或现象的基本原因。','重复数据是错误根源。'),C('root.s3','生根；翻找；为……加油','At the playoff, fans rooted for the home team while gardeners rooted the cuttings in damp soil.','季后赛上球迷为主队加油，而园丁把插枝栽进湿土里使其生根。','Fans rooted for the home team / while gardeners rooted cuttings / in damp soil.','root.s3 可指生根、仔细翻找，也可指为某队加油。','同句展示 root 的动词用法。')],M('The investigator found the root of the error by ignoring the database and blaming a random garden plant.','The investigator found the root of the error by tracing it to a duplicated database entry.','忽略数据来源并任意归咎植物不能找出错误的根源。','meaning'),[q('Why did the oak’s root grow deep into the soil?','to draw water during the dry summer','to cheer for the home team','to duplicate a database entry','树根深入土壤以在干旱季节吸收水分。',1,'context'),q('What was the root of the billing error?','a duplicated database entry','a thirsty oak tree','a playoff crowd','调查发现账单错误源于重复数据。',2,'context'),q('Who rooted for the home team?','the fans at the playoff','the gardeners planting cuttings','the hotel roommates','球迷在季后赛为主队加油。',3,'context'),q('What does root mean in “the root of the error”?','the basic cause','the underground plant part','the act of cheering','这里 root 指错误的根本原因。',2,'meaning')]);
P('rooted','Rooted is the past participle of root; it describes a plant fixed by roots or a person, habit, or belief deeply established in a place or tradition.',C('rooted.s1','扎根的；根深蒂固的','The family is rooted in the coastal town, where four generations have worked in the fishing industry.','这个家庭扎根于这座海滨小镇，四代人都从事渔业。','The family is rooted in the coastal town / where four generations / worked in fishing.','rooted 可指植物扎根，也可比喻人或观念深深建立在某处。','几代人都生活在同一海滨社区。'),M('The family was rooted in the town even though it had never lived there and had no ties to the place.','The family was rooted in the town after four generations built their lives there.','从未居住、没有联系，不能说家庭扎根于当地。','meaning'),[q('How many generations of the family worked in fishing?','four','one','seven','这个家庭四代人在海滨小镇从事渔业。',1,'context'),q('What does rooted describe about the family?','deeply established in the town','moving through the town for one day','having no connection to the town','rooted 表示家庭深深扎根于小镇。',1,'meaning'),q('Which belief is rooted in a community?','a tradition practiced by generations','a temporary slogan nobody follows','a rule that was just revoked','代代相传的传统深深扎根于社区。',1,'context'),q('Which verb is rooted derived from?','root','roost','room','rooted 是 root 的过去分词，也可作形容词。',1,'word-formation')]);
P('rootless','Rootless combines root and -less; it describes a plant lacking roots or a person not firmly connected to a place or community.',C('rootless.s1','无根的；无归属感的','After moving between temporary jobs and apartments for years, Kai felt rootless and struggled to build lasting friendships.','多年在临时工作和住所之间辗转后，凯感到缺乏归属感，很难建立长久友谊。','Kai felt rootless / after years of temporary jobs / and changing apartments.','rootless 可指植物无根，也可形容人缺少稳定的地方或社群联系。','长期漂泊使凯感到无归属感。'),M('Kai felt rootless because he had lived in the same close-knit neighborhood all his life and had lasting community ties.','Kai felt rootless because he had moved repeatedly and lacked lasting ties to a place.','长期定居且有稳定社区关系与无归属感相反。','meaning'),[q('What made Kai feel rootless?','years of changing jobs and apartments','four generations in one coastal town','a roomy minivan','凯多年更换工作和住所，缺少稳定归属感。',1,'context'),q('What does rootless mean about a person?','not firmly connected to a place or community','having a deep plant root','supporting a chess team','rootless 可指缺少稳定的地方或社群联系。',1,'meaning'),q('Which person might feel rootless?','someone who has moved repeatedly and lacks a community','someone whose family has lived in one town for generations','someone with a rooted belief in a tradition','反复迁居且缺乏社区联系的人可能感到 rootless。',1,'context'),q('What does the suffix -less mean in rootless?','without','full of','able to','-less 表示“没有”，rootless 即“无根的”。',1,'word-formation')]);
P('rope','Rope comes from Old English rāp; it can mean a strong twisted line, tie something with rope, or persuade someone to help, often in rope in.',[C('rope.s1','绳；绳索','The rescue team lowered a thick rope over the cliff so the stranded climber could reach the ledge.','救援队把粗绳放下悬崖，让被困的攀岩者够到岩架。','The team lowered a thick rope / over the cliff / for the stranded climber.','rope.s1 指由纤维拧成的粗而结实的线。','粗绳帮助攀岩者脱困。'),C('rope.s2','用绳捆；用绳圈起','Workers roped off the wet floor until the cleaning crew finished.','清洁人员完成工作前，工人用绳子围起了湿滑地面。','Workers roped off the wet floor / until the cleaning crew / finished.','rope.s2 作动词，指用绳捆绑或围住。','绳子隔开湿滑地面。'),C('rope.s3','说服；拉……帮忙','Maya roped her brother into carrying the heavy boxes up three flights of stairs.','玛雅说服哥哥帮忙把沉重的箱子搬上三层楼。','Maya roped her brother into carrying boxes / up three flights / of stairs.','rope.s3 常见于 rope someone into，指说服某人参与或帮忙。','哥哥被说服来搬箱子。')],M('The rescue team lowered a rope by placing a soft paper ribbon over the cliff that could not support the climber.','The rescue team lowered a thick rope strong enough to help the climber reach the ledge.','纸丝带不能支撑攀岩者，不是用于救援的结实绳索。','meaning'),[q('What did the rescue team lower over the cliff?','a thick rope','a rosette badge','a rice field','救援队放下一根粗绳帮助攀岩者。',1,'context'),q('Why did workers rope off the wet floor?','to keep people away until cleaning was finished','to persuade a brother to move boxes','to mark a chess file','工人用绳子围起湿滑地面，直到清洁完成。',2,'context'),q('What did Maya rope her brother into doing?','carrying heavy boxes upstairs','playing a rooster in a play','reviewing the wet floor','玛雅说服哥哥帮忙搬沉重箱子。',3,'context'),q('What does “rope someone into” mean?','persuade someone to take part or help','tie a person up with a line','lower someone over a cliff','rope someone into 指说服某人参与或帮忙。',3,'meaning')]);
P('rose','Rose comes from Latin rosa, the name of the flower; it means the thorn-stemmed flower or a pink-red color named after it.',[C('rose.s1','玫瑰；蔷薇','A rose opened beside the garden gate, its petals bright against the dark leaves.','花园门旁一朵玫瑰盛开，花瓣在深色叶片映衬下格外鲜艳。','A rose opened beside the gate / its petals bright / against dark leaves.','rose.s1 指生长在带刺灌木上的花。','玫瑰花在花园里盛开。'),C('rose.s2','玫瑰色；玫瑰红','She chose a rose scarf whose pink-red shade matched the lining of her coat.','她选了一条玫瑰红围巾，粉红色调与大衣内衬相配。','She chose a rose scarf / whose pink-red shade / matched her coat lining.','rose.s2 可作颜色名，指粉红偏红的色调。','围巾呈玫瑰红色。')],M('The rose bloomed on a thornless metal pole and produced no flower petals.','The rose bloomed on a thorny bush and opened bright petals.','没有花瓣且不是植物的金属杆不是玫瑰。','meaning'),[q('Where did the rose open?','beside the garden gate','inside the dormitory room','on the chessboard','玫瑰在花园门旁盛开。',1,'context'),q('What color was the scarf?','pink-red','dark green','pale gray','围巾是玫瑰红色。',2,'context'),q('What does rose mean in the garden sentence?','a flower on a thorny bush','a shade of pink-red','a ribbon-shaped award','花园句中的 rose 指玫瑰花。',1,'meaning'),q('What does rose mean in “a rose scarf”?','pink-red in color','a flower growing in a pot','a place where hens sleep','rose scarf 中 rose 指玫瑰红色。',2,'meaning')]);
P('rosette','Rosette came through French rosette, a diminutive of rose; it means a ribbon badge or carved ornament shaped like a rose.',C('rosette.s1','玫瑰状饰物；奖章','The winning mare wore a blue rosette pinned to her bridle after the county show.','赢得郡展的母马缰绳上别着一枚蓝色玫瑰形奖章。','The winning mare wore a blue rosette / pinned to her bridle / after the show.','rosette 指玫瑰形的丝带徽章或雕刻装饰。','马匹获奖后佩戴玫瑰形饰章。'),M('The mare wore a rosette shaped like a plain square metal plate with no ribbon folds or floral design.','The mare wore a ribbon rosette folded into a rose-shaped badge.','没有玫瑰形或丝带形状的方形金属片不是 rosette。','meaning'),[q('Where was the mare’s rosette pinned?','to her bridle','to the hotel room door','to a wet floor rope','蓝色玫瑰形奖章别在母马的缰绳上。',1,'context'),q('Why was the mare wearing the rosette?','she won the county show','she was a roommate','she was a chess rook','获胜的母马佩戴奖章。',1,'context'),q('What is a rosette?','a rose-shaped ribbon badge or ornament','a strong line made of twisted fibers','a flower’s underground part','rosette 是玫瑰形丝带徽章或装饰。',1,'meaning'),q('What does the French diminutive rosette refer to in its origin?','a small rose-like form','a long twisted rope','a wooden bird perch','rosette 的词源是法语 rose 的指小形式。',1,'word-formation')]);
P('rostrum','Rostrum comes from Latin rostrum, “beak,” later used for the beak-shaped platform in ancient Rome; today it means a raised platform for a speaker or official.',C('rostrum.s1','讲坛；演讲台','The student stepped onto the rostrum and addressed the audience about protecting the local wetlands.','学生走上讲台，向听众发表保护当地湿地的演讲。','The student stepped onto the rostrum / and addressed / the audience about wetlands.','rostrum 指演讲者或官员站立讲话的高台。','学生在讲台上发表讲话。'),M('The student addressed the audience from the rostrum while standing beneath the floor and hidden from view.','The student addressed the audience from the raised rostrum at the front of the hall.','位于地板下而非高台上，不符合 rostrum 的意思。','meaning'),[q('What did the student discuss from the rostrum?','protecting local wetlands','how to repair an oak root','how to grow rice','学生在讲台上发表保护湿地的演讲。',1,'context'),q('What is a rostrum?','a raised platform for a speaker','a bird’s sleeping perch','a circular traffic junction','rostrum 指演讲者使用的高台。',1,'meaning'),q('Where was the student when addressing the audience?','on the platform at the hall’s front','under the floor and out of sight','inside a roomy minivan','学生站在大厅前方的讲台上讲话。',1,'context'),q('Which older Latin meaning is connected with rostrum?','beak','flower','rope','rostrum 源自拉丁语“鸟喙”，后来指讲台。',1,'word-formation')]);
P('rosy','Rosy is formed from rose and -y; it describes a pink color or healthy pink complexion, and can mean optimistic or promising.',[C('rosy.s1','红润的；玫瑰色的','After the brisk walk in the cold air, the child’s cheeks looked rosy.','在冷空气中快步走后，孩子的脸颊显得红润。','The child’s cheeks looked rosy / after the brisk walk / in cold air.','rosy.s1 可指玫瑰色，也可指健康红润的脸色。','冷空气和运动使脸颊泛红。'),C('rosy.s2','乐观的；前景光明的','The first sales figures looked rosy, but the manager waited for a full quarter of results before celebrating.','首批销售数据看起来很乐观，但经理等完整季度结果出来后才庆祝。','The first sales figures looked rosy / but the manager waited / for a full quarter.','rosy.s2 指使人觉得某事很可能成功或发展顺利。','初期销售结果让人对前景乐观。')],M('The child’s cheeks looked rosy because they were pale, blue, and showed no trace of pink after exercise.','The child’s cheeks looked rosy because exercise gave them a healthy pink color.','苍白发蓝而无粉红色不能称为 rosy cheeks。','meaning'),[q('What made the child’s cheeks look rosy?','a brisk walk in cold air','a sales report','a chess match','孩子在冷空气中快步走后脸颊发红。',1,'context'),q('Why did the manager wait before celebrating?','the rosy figures covered only the first sales period','the sales figures had already fallen to zero','the child had left the room','经理等完整季度数据后再庆祝，尽管初期结果乐观。',2,'context'),q('What does rosy mean about the child’s cheeks?','pink and healthy-looking','deeply rooted in soil','made of a ribbon','rosy cheeks 指红润的脸颊。',1,'meaning'),q('What does rosy mean in “a rosy outlook”?','optimistic and promising','pink-red in color','a result that was revoked','a rosy outlook 指乐观、有希望的前景。',2,'meaning')]);
P('rot','Rot comes from Old English rotian or related Germanic forms; it can mean decay as a verb, decay as a process or result, or nonsense as an informal noun.',[C('rot.s1','腐烂；腐坏','If the pears stay in the damp crate, they will rot before the market opens.','如果梨一直放在潮湿的箱子里，集市开门前就会腐烂。','The pears will rot / if they stay / in the damp crate.','rot.s1 作动词，指自然腐败并变软、变坏。','潮湿环境会使梨腐烂。'),C('rot.s2','腐烂；腐朽','The inspector found rot in the wooden beam and ordered the bridge closed for repairs.','检查员在木梁中发现腐朽，随即下令关闭桥梁维修。','The inspector found rot / in the wooden beam / and closed the bridge.','rot.s2 作名词，指腐烂的过程或腐坏部分。','腐朽木梁使桥梁不安全。'),C('rot.s3','胡说；废话','“That the moon is made of cheese is rot,” the science teacher told the class.','科学老师告诉全班：“月亮是奶酪做的，那是胡说。”','The teacher called the claim rot / and explained / that the moon is rock.','rot.s3 是非正式用法，指荒唐或不真实的话。','老师否定了荒谬的说法。')],M('The pears began to rot by becoming firmer, fresher, and safer to eat after weeks in the damp crate.','The pears began to rot by becoming soft and spoiled in the damp crate.','变得更鲜更安全与腐坏相反。','meaning'),[q('What happened to pears left in the damp crate?','they became spoiled','they grew a root','they turned into a rosette','潮湿箱子里的梨会腐烂。',1,'context'),q('What did the inspector find in the beam?','decay in the wood','a room for one more chair','a pink-red color','检查员发现木梁腐朽。',2,'context'),q('What did the teacher call the cheese-moon claim?','nonsense','a root cause','a rosy prediction','老师称月亮由奶酪组成的说法是胡说。',3,'context'),q('Which use of rot means “decay”?','The fruit will rot in the damp crate.','That story is rot.','The beam contains rot.','第一句的 rot 是动词，表示腐烂。',1,'meaning')]);
P('rota','Rota comes through Latin rota, “wheel,” and names a rotating schedule that assigns different people to duties at different times.',C('rota.s1','轮值表；值勤表','The clinic posted a rota showing which nurse would cover the night shift each day.','诊所张贴了一份轮值表，列明每天由哪位护士值夜班。','The clinic posted a rota / showing which nurse / covered each night shift.','rota 指列出不同时间值班人员的书面安排表。','护士按表轮流值夜班。'),M('The clinic’s rota assigned every night shift to nobody and gave no information about who was on duty.','The clinic’s rota listed the nurse assigned to each night shift.','没有安排值班人员的表格不符合 rota 的作用。','meaning'),[q('What did the clinic’s rota show?','which nurse covered each night shift','which fruit would rot in storage','where the rooster would roost','轮值表列明每天由谁值夜班。',1,'context'),q('What is a rota?','a written schedule assigning people to duties','a circular road junction','a flower-shaped badge','rota 是轮流安排值班的书面表格。',1,'meaning'),q('How were night shifts assigned?','different nurses covered them on different days','one nurse was assigned every day forever','no nurse was listed','护士按照轮值表在不同日期轮流值夜班。',1,'context'),q('Which Latin word is related to rota?','rota, “wheel”','rosa, “rose”','rōt, “root”','rota 源自拉丁语“轮子”，联想到轮流安排。',1,'word-formation')]);
P('rotary','Rotary is from Latin rotarius, from rota (“wheel”); it describes movement around an axis and can name a circular traffic junction.',[C('rotary.s1','旋转的','The rotary blade cuts the paper as it spins around its central axis.','旋转刀片绕着中心轴转动时切割纸张。','The rotary blade cuts the paper / as it spins / around its central axis.','rotary.s1 描写绕某根轴旋转或运作的。','刀片绕轴转动。'),C('rotary.s2','环岛；环形交叉路口','Drivers entering the rotary slowed down and yielded to traffic already circling the central island.','驶入环岛的司机减速，让行已经绕中心岛行驶的车辆。','Drivers entering the rotary slowed down / and yielded / to circulating traffic.','rotary.s2 指车辆绕中央岛行驶的环形交叉路口。','司机驶入环岛并礼让环行车辆。')],M('The rotary blade cut the paper while remaining completely still and never turning around its axis.','The rotary blade cut the paper as it turned around its central axis.','静止不转的刀片不是旋转的。','meaning'),[q('How does the rotary blade cut paper?','it spins around a central axis','it remains fixed and does not move','it follows traffic around an island','旋转刀片绕中心轴转动来切纸。',1,'context'),q('What did drivers do at the rotary?','yielded to traffic circling the central island','drove straight through without slowing','parked on the central island','司机进入环岛时让行已经环行的车辆。',2,'context'),q('What does rotary mean in “rotary blade”?','moving around an axis','a schedule assigning shifts','a flower-shaped badge','rotary blade 中 rotary 指旋转的。',1,'meaning'),q('What does rotary mean in traffic?','a circular junction around a central island','a tool that cuts while stationary','a room with many windows','交通语境中的 rotary 指环形交叉路口。',2,'meaning')]);
P('rotate','Rotate comes from Latin rotare, from rota (“wheel”); it means turn around a central point or take turns in a job or position.',[C('rotate.s1','旋转；转动','Rotate the handle clockwise until the red mark lines up with the arrow.','顺时针旋转把手，直到红色标记与箭头对齐。','Rotate the handle clockwise / until the red mark / lines up with the arrow.','rotate.s1 指围绕中心点或轴转动。','把手转动到标记对齐的位置。'),C('rotate.s2','轮流；轮换','The four interns rotate through the laboratory stations so each person learns every procedure.','四名实习生轮流到实验室各工位学习，以便每个人掌握所有流程。','The interns rotate through the stations / so each person / learns every procedure.','rotate.s2 指按顺序轮流担任工作或职位。','实习生依次轮换工位。')],M('Rotate the handle clockwise by holding it fixed in one position and preventing it from turning.','Rotate the handle clockwise by turning it around its central axis.','固定把手使其不能转动，与 rotate 的旋转义相反。','meaning'),[q('In which direction should the handle rotate?','clockwise','counterclockwise','straight upward without turning','把手应顺时针旋转，直到标记对齐。',1,'context'),q('How do interns rotate through laboratory stations?','they take turns at different stations','they remain at one station all year','they turn the stations around an axis','实习生轮流到不同工位学习。',2,'context'),q('What does rotate mean in the handle instruction?','turn around a central point','take turns at a position','return something to a former owner','这里 rotate 指转动把手。',1,'meaning'),q('What does rotate mean in the internship program?','take turns at jobs or positions','spin the handle clockwise','cause fruit to decay','实习语境中 rotate 指轮流担任不同岗位。',2,'meaning')]);
P('rotation','Rotation comes from Latin rotatio, from rotare (“turn”); it means the act or one complete turn around a fixed center, or a regular change of people or jobs.',[C('rotation.s1','旋转；转动','One rotation of the wheel moves the conveyor belt forward by twenty centimeters.','轮子转一周，传送带便向前移动二十厘米。','One rotation of the wheel / moves the conveyor belt / twenty centimeters.','rotation.s1 指绕固定中心转动的动作或完整一圈。','轮子每转一周，传送带前进固定距离。'),C('rotation.s2','轮换；轮流','A rotation of staff ensures that someone trained in first aid is present on every shift.','员工轮班安排确保每个班次都有受过急救训练的人在岗。','A staff rotation ensures / someone trained in first aid / is present each shift.','rotation.s2 指人员或工作按规律轮流更换。','排班轮换保障每班都有急救人员。')],M('One rotation of the wheel moved the belt by twenty centimeters even though the wheel made no turn at all.','One rotation of the wheel moved the belt after the wheel completed one full turn.','轮子没有转动就不可能完成 rotation。','meaning'),[q('How far did the conveyor belt move per wheel rotation?','twenty centimeters','two meters','one millimeter','轮子转一周，传送带前进二十厘米。',1,'context'),q('What does the staff rotation ensure?','a trained first-aid worker is present on every shift','the same person works every shift','the wheel turns once each day','人员轮换确保每班有受过急救训练的人。',2,'context'),q('What does rotation mean in the wheel example?','one complete turn around a fixed center','a schedule of workers taking turns','a circular road junction','轮子的 rotation 指绕中心完成一整圈。',1,'meaning'),q('What does rotation mean in “a rotation of staff”?','a regular change of people taking turns','a single full turn of a wheel','the act of returning to a former condition','staff rotation 指员工按规律轮班。',2,'meaning')]);
P('rotational','Rotational comes from rotation and -al; it describes motion around a central point or an arrangement in which people take turns.',[C('rotational.s1','旋转的','The laboratory measured the rotational speed of the turbine as its blades circled the central shaft.','实验室测量了涡轮叶片绕中心轴旋转时的转速。','The laboratory measured rotational speed / as the blades circled / the central shaft.','rotational.s1 指绕中心点或轴作圆周运动的。','涡轮叶片围绕轴旋转。'),C('rotational.s2','轮流的','A rotational schedule gives each technician a week on the day shift before the next person takes over.','轮换排班让每位技师先值一周白班，再由下一位接班。','A rotational schedule gives each technician / a week on days / before the next takes over.','rotational.s2 指按固定顺序安排人员轮流承担任务。','技师按顺序轮班。')],M('The turbine had rotational motion because its blades stayed fixed and never moved around the shaft.','The turbine had rotational motion because its blades circled the central shaft.','叶片固定不动就没有旋转运动。','meaning'),[q('What did the lab measure?','the turbine blades’ rotational speed','how often technicians changed shifts','the length of a route','实验室测量了涡轮叶片的旋转速度。',1,'context'),q('How does the rotational schedule assign work?','technicians take turns in a fixed order','one technician works every day shift','each person chooses a random job','轮换排班让技师按顺序轮值。',2,'context'),q('What does rotational mean about the turbine?','moving around a central axis','arranged by people taking turns','having an uneven surface','这里 rotational 描写绕中心轴转动。',1,'meaning'),q('What does rotational mean in “rotational schedule”?','organized so people take turns','moving around a central point','rough and difficult','rotational schedule 指按顺序轮换的排班。',2,'meaning')]);
P('rote','Rote appears in the phrase learning by rote for memorizing through repetition; its deeper etymology is uncertain.',C('rote.s1','死记硬背','The pupil learned the multiplication table by rote but struggled to explain why the answers worked.','这名学生靠死记硬背学会了乘法表，却难以解释答案为何成立。','The pupil learned the table by rote / but struggled / to explain the answers.','rote 指单靠重复记忆学习，而非理解原理。','学生记住答案但没有理解。'),M('She learned the formula by rote by deriving it from first principles and never repeating it aloud.','She learned the formula by rote by repeating it until she could recite it without understanding why.','通过推导理解原理而非机械背诵，不符合 by rote。','meaning'),[q('What did the pupil struggle to explain?','why the multiplication answers worked','how the tide moved around an axis','why the market was spacious','学生记住了乘法表答案，却不理解原因。',1,'context'),q('What does “learn by rote” mean?','memorize by repetition without necessarily understanding','learn by testing each idea in an experiment','teach someone by taking turns','by rote 指靠重复记忆，不一定理解。',1,'meaning'),q('Which is learning by rote?','reciting a list repeatedly without knowing its meaning','explaining each item and applying it to new problems','discovering a new route through a forest','反复背诵但不懂意思属于死记硬背。',1,'context'),q('What does the source say about rote’s deeper origin?','it is uncertain','it comes directly from rotational','it is formed from row and -age','rote 的更深层词源并不确定。',1,'word-formation')]);
P('rotten','Rotten is the past participle of rot; it can describe decayed food, something very bad informally, or corrupt and dishonest behavior.',[C('rotten.s1','腐烂的；腐朽的','The rotten peaches smelled sour, so the grocer removed them from the display.','腐烂的桃子散发酸味，杂货商便把它们从货架上撤下。','The rotten peaches smelled sour / so the grocer / removed them.','rotten.s1 指自然腐败、变软并发出异味的。','腐坏的水果不再出售。'),C('rotten.s2','糟透的；极差的','The hikers had a rotten day when heavy rain soaked their gear and the trail was closed.','大雨淋湿装备、步道又关闭，徒步者度过了糟糕的一天。','The hikers had a rotten day / when rain soaked their gear / and the trail closed.','rotten.s2 是口语，表示非常糟糕或令人不快。','坏天气让旅程很糟。'),C('rotten.s3','腐败的；堕落的','The investigation exposed a rotten deal in which officials accepted secret payments to award contracts.','调查揭露了一笔腐败交易：官员收受秘密款项后授予合同。','The investigation exposed a rotten deal / involving secret payments / for contracts.','rotten.s3 比喻道德败坏、不诚实的。','官员收受贿赂构成腐败行为。')],M('The rotten peaches smelled fresh and sweet and remained safe to sell for weeks.','The rotten peaches smelled sour and had begun to decay.','新鲜甜美且可长期出售的桃子不是腐烂的。','meaning'),[q('Why did the grocer remove the peaches?','they had spoiled and smelled sour','the trail had closed','the officials had rotated shifts','桃子腐烂发酸，因此被杂货商撤下。',1,'context'),q('Why did the hikers have a rotten day?','rain soaked their gear and the trail closed','they memorized a table by rote','they took turns on a schedule','暴雨和封路让徒步者度过糟糕的一天。',2,'context'),q('What made the contract deal rotten?','officials accepted secret payments','the fruit had spoiled','the route was indirect','官员收受秘密款项说明交易腐败。',3,'context'),q('Which use of rotten means “morally corrupt”?','a rotten deal involving bribes','rotten peaches on a display','a rotten day in the rain','rotten deal 指道德上腐败的交易。',3,'meaning')]);
P('rough','Rough comes from Old English rūh, “uneven or shaggy”; it can describe an uneven surface, an approximate estimate, or difficult, violent, or stormy conditions.',[C('rough.s1','粗糙的；不平的','The carpenter sanded the rough edge of the shelf until it felt smooth to the touch.','木匠把架子的粗糙边缘打磨到摸起来光滑为止。','The carpenter sanded the rough edge / until it felt / smooth to the touch.','rough.s1 指表面不平滑、有凹凸。','打磨去除木边的粗糙感。'),C('rough.s2','大致的；粗略的','Before measuring every wall, the builder gave the family a rough estimate of the renovation cost.','逐一测量所有墙面前，施工方先给这家人报了一个粗略的翻修费用。','The builder gave a rough estimate / before measuring / every wall.','rough.s2 指不精确或不完整的估算。','先提供大致费用。'),C('rough.s3','艰难的；粗暴的；风浪大的','The fishing boat faced rough seas on its return, and the crew secured every loose container.','渔船返航时遇到风浪，船员把所有松动的容器固定好。','The boat faced rough seas / on its return / so the crew secured containers.','rough.s3 指困难、猛烈或波涛汹涌的情况。','海上风浪很大。')],M('The carpenter called the shelf edge rough because it was perfectly smooth and had no uneven spots.','The carpenter called the shelf edge rough because it had splinters and an uneven surface.','完全光滑的表面不是粗糙的。','meaning'),[q('What did the carpenter do to the rough edge?','sanded it until it felt smooth','estimated the renovation cost','secured containers in rough seas','木匠打磨了架子粗糙的边缘。',1,'context'),q('Was the builder’s cost estimate exact?','no, it was approximate','yes, every wall had been measured','it described the sea conditions','施工方提供的是粗略估价。',2,'context'),q('What did the fishing boat face?','stormy, rough seas','a smooth shelf edge','an orderly shift rota','渔船返航时遇到风浪。',3,'context'),q('What does rough mean in “rough estimate”?','not exact or complete','uneven to the touch','difficult because of large waves','rough estimate 指不精确的大致估算。',2,'meaning')]);
P('rough it','Rough it is an informal phrase meaning live or stay without the usual food, beds, or comforts.',C('rough it.s1','艰苦凑合；简陋过活','The campers decided to rough it for two nights, sleeping in tents and cooking over a small fire.','露营者决定凑合过两晚，睡在帐篷里并用小火做饭。','The campers decided to rough it / sleeping in tents / and cooking outdoors.','rough it 指暂时没有平日享受的舒适条件。','露营者没有住旅馆或用厨房。'),M('The campers roughed it in a luxury hotel with room service, soft beds, and a private chef.','The campers roughed it by sleeping in tents and preparing simple meals outdoors.','享有酒店服务和舒适床铺不属于艰苦凑合。','meaning'),[q('Where did the campers sleep while they roughed it?','in tents','in a luxury hotel','in a roomy dormitory','露营者睡在帐篷里，没有住旅馆。',1,'context'),q('How did they prepare food?','over a small outdoor fire','with a private chef','by ordering room service','他们用小火在户外做饭。',1,'context'),q('What does rough it mean?','stay without the usual comforts','choose a comfortable hotel','estimate a cost approximately','rough it 指没有平日舒适条件地生活或住宿。',1,'meaning'),q('Which trip would involve roughing it?','a weekend camping without beds or indoor plumbing','a resort stay with room service','a city tour by luxury bus','没有床铺和室内水管的露营属于 rough it。',1,'context')]);
P('roughage','Roughage combines rough and -age; it means dietary fiber in whole grains and vegetables that helps food pass through the digestive system.',C('roughage.s1','粗纤维；膳食纤维','The dietitian added beans and whole-grain bread to increase the roughage in the patient’s meals.','营养师在病人的餐食中加入豆类和全谷物面包，以增加膳食纤维。','The dietitian added beans and whole grains / to increase roughage / in the meals.','roughage 指帮助食物通过身体的膳食纤维。','豆类和全谷物能增加纤维摄入。'),M('The dietitian increased roughage by removing all vegetables and whole grains from the patient’s meals.','The dietitian increased roughage by adding beans, vegetables, and whole grains.','去除蔬菜和全谷物会减少膳食纤维。','meaning'),[q('What foods did the dietitian add?','beans and whole-grain bread','rotten peaches','a ribbon and a rosette','营养师加入豆类和全谷物面包来增加纤维。',1,'context'),q('What does roughage help do?','help food pass through the body','make a surface rough to touch','assign shifts by rotation','roughage 有助于食物通过消化系统。',1,'meaning'),q('Which meal is richest in roughage?','one with beans, vegetables, and whole grains','one with only clear broth and sugar','one containing a ribbon-shaped badge','豆类、蔬菜和全谷物富含膳食纤维。',1,'context'),q('Which suffix is used in the noun roughage?','-age','-less','-er','rough 加 -age 构成名词 roughage。',1,'word-formation')]);
P('roughly','Roughly is formed from rough and -ly; it can mean approximately or in a harsh, violent, or forceful manner.',[C('roughly.s1','大致上；大约','Roughly three hundred people attended the open-air concert, according to the organizer’s estimate.','据组织者估计，大约有三百人参加了露天音乐会。','Roughly three hundred people attended / according to / the organizer’s estimate.','roughly.s1 表示数量或程度大约如此，并非精确数字。','人数是估算值。'),C('roughly.s2','粗暴地；猛烈地','The guard handled the old suitcase roughly and cracked one of its wooden corners.','警卫粗暴地搬动旧手提箱，弄裂了一个木角。','The guard handled the suitcase roughly / and cracked / a wooden corner.','roughly.s2 表示动作粗暴或不温和。','搬运方式导致箱角破裂。')],M('Roughly three hundred people attended means that the organizer counted exactly 300 named guests without any estimate.','Roughly three hundred people attended means the number was approximate.','roughly 表示大约，不承诺精确计数。','meaning'),[q('How many people attended the concert?','about three hundred','exactly thirty','roughly three thousand musicians','组织者估计大约三百人参加。',1,'context'),q('How did the guard handle the suitcase?','in a harsh way that cracked a corner','gently without touching it','approximately three times','警卫粗暴搬运手提箱，弄裂了一个角。',2,'context'),q('What does roughly mean before a number?','approximately','violently','in a circular path','数量前的 roughly 表示大约。',1,'meaning'),q('What does roughly describe in “handled roughly”?','a harsh manner','an approximate count','a dietary fiber','handled roughly 指粗暴地搬动。',2,'meaning')]);
P('roughness','Roughness is formed from rough and -ness; it names an uneven surface or a harsh manner.',C('roughness.s1','粗糙；崎岖','The roughness of the stone path made the delivery cart rattle as it crossed the courtyard.','石路表面崎岖，运货车经过院子时颠簸作响。','The roughness of the path / made the delivery cart / rattle across the courtyard.','roughness 指表面不平的状态，也可指态度粗暴。','石路凹凸不平使车轮震动。'),M('The roughness of the stone path made the cart rattle even though the surface was polished and perfectly even.','The roughness of the stone path made the cart rattle because the surface was uneven.','平整光滑的路面没有 roughness。','meaning'),[q('What did the rough path make rattle?','the delivery cart','the rooster','the chess rook','崎岖的石路让运货车颠簸作响。',1,'context'),q('What does roughness describe here?','an uneven surface','a large amount of dietary fiber','an approximate number','这里 roughness 指石路表面不平。',1,'meaning'),q('Which object has roughness?','a stone with a bumpy surface','a pane polished until it is smooth','a room with more floor space','凹凸不平的石头具有 roughness。',1,'context'),q('Which suffix forms roughness?','-ness','-age','-ly','rough 加 -ness 形成表示状态的名词 roughness。',1,'word-formation')]);
P('round','Round comes through French rond from Latin rotundus, “round”; it can describe a circular shape, mean around/about, name a competition stage or set of drinks, or mean go around/make curved.',[C('round.s1','圆的；球形的','The potter shaped the clay into a round bowl with a smooth circular rim.','陶艺师把陶土做成一个圆碗，碗口平滑呈圆形。','The potter shaped the clay / into a round bowl / with a circular rim.','round.s1 描写圆形或球形。','碗沿呈圆形。'),C('round.s2','环绕；在周围；大约','We walked round the lake and returned to the visitor center in about an hour.','我们绕湖走了一圈，大约一小时后回到游客中心。','We walked round the lake / and returned / in about an hour.','round.s2 可指围绕、在周围，也可表示大约。','路线环绕湖泊；时间约一小时。'),C('round.s3','一轮；一回合；一场','She advanced to the final round of the chess tournament after winning three matches.','她赢下三场比赛后晋级国际象棋锦标赛的最后一轮。','She advanced to the final round / after winning / three matches.','round.s3 指比赛的一阶段或一轮。','棋手进入最后一轮。'),C('round.s4','绕过；使成圆形','The driver rounded the bend slowly because the road was icy.','由于道路结冰，司机缓慢地绕过弯道。','The driver rounded the bend / slowly / because the road was icy.','round.s4 作动词，指绕过某物或使其变圆。','司机绕过结冰的弯道。')],M('The potter made a round bowl with four straight sides and sharp square corners.','The potter made a round bowl with a circular shape and curved rim.','四条直边和方角构成方形而非圆形。','meaning'),[q('What shape did the potter give the bowl?','circular','square with four sharp corners','a line with no curve','陶艺师将碗做成圆形。',1,'context'),q('How long did the walk round the lake take?','about an hour','exactly three matches','a full day','绕湖散步大约花了一小时。',2,'context'),q('Which round did the chess player reach?','the final stage','the opening practice only','the driver’s bend','棋手赢下三场后进入最后一轮。',3,'context'),q('What did the driver round?','the icy bend','the circular bowl','the chess tournament','司机缓慢绕过结冰的弯道。',4,'context')]);
P('roundabout','Roundabout combines round and about; as an adjective it means indirect, and as a noun it means a circular road junction around a central island.',[C('roundabout.s1','迂回的；不直接的','Rather than answer directly, he gave a roundabout explanation that took ten minutes to reach the point.','他没有直接回答，而是绕了十分钟才说到重点。','He gave a roundabout explanation / that took ten minutes / to reach the point.','roundabout.s1 指表达或路线迂回、不直接。','解释绕远才切入要点。'),C('roundabout.s2','环岛；环形交叉路口','At the roundabout, the driver yielded to a bus already circulating around the central island.','在环岛处，司机让行已经绕中心岛行驶的公交车。','At the roundabout, the driver yielded / to a bus / circling the central island.','roundabout.s2 指车辆围绕中央岛行驶的道路交叉口。','司机进入环岛时礼让公交车。')],M('He gave a roundabout answer by stating his conclusion clearly in one direct sentence.','He gave a roundabout answer by describing several side issues before reaching his point.','直接简洁的回答不是迂回的表达。','meaning'),[q('Why was the explanation roundabout?','it took ten minutes to reach the point','it gave the answer in one direct sentence','it described how to round a bowl','解释绕了十分钟才说到重点。',1,'context'),q('What did the driver yield to?','a bus circling the central island','a pedestrian in a bedroom','a rook on the chessboard','司机在环岛让行已经环行的公交车。',2,'context'),q('What does roundabout mean about an explanation?','indirect and not going straight to the point','circular and shaped like a wheel','approximately ten minutes long','roundabout explanation 指迂回、不直接的解释。',1,'meaning'),q('What is a roundabout in traffic?','a junction where vehicles circulate around an island','an approximate walking time','an indirect answer','交通中的 roundabout 是车辆绕中心岛行驶的环岛。',2,'meaning')]);
P('rounded','Rounded is the past participle of round; it describes a curved form or something complete and balanced in its qualities.',[C('rounded.s1','圆润的；圆形的','The sculptor softened the statue’s rounded shoulders so there were no sharp corners.','雕塑家把雕像圆润的肩部打磨得更加柔和，不留尖角。','The sculptor softened the rounded shoulders / so they had / no sharp corners.','rounded.s1 指边缘弯曲、不尖锐或棱角分明的形状。','雕像肩部曲线柔和。'),C('rounded.s2','全面的；均衡的','The course gives students a rounded education by combining science, history, writing, and art.','这门课程把科学、历史、写作和艺术结合起来，为学生提供全面均衡的教育。','The course gives students a rounded education / by combining / four subject areas.','rounded.s2 指内容完整、均衡而全面。','课程包含多个学科领域。')],M('The sculptor made the shoulders rounded by carving sharp angular points along every edge.','The sculptor made the shoulders rounded by smoothing their curved edges.','刻出尖锐棱角会让形状有角，而非圆润。','meaning'),[q('How did the sculptor shape the shoulders?','with smooth curves and no sharp corners','with sharp angular points','with a circular traffic island','雕塑家把肩部打磨成没有尖角的圆润形状。',1,'context'),q('What subjects create the course’s rounded education?','science, history, writing, and art','one subject repeated by rote','only traffic rules','课程结合科学、历史、写作和艺术，提供全面教育。',2,'context'),q('What does rounded mean about the shoulders?','curved rather than angular','complete in several academic fields','moving around an axis','rounded shoulders 指曲线圆润、不带尖角的肩部。',1,'meaning'),q('What does a rounded education mean?','complete and balanced in important areas','curved like a circle','limited to one narrow subject','rounded education 指全面、均衡的教育。',2,'meaning')]);
P('rouse','Rouse has uncertain deeper origins; it means wake someone from sleep or stir someone to anger, activity, or excitement.',[C('rouse.s1','唤醒；使醒来','The alarm roused the night guard from a light sleep just before the security gate opened.','安全门打开前不久，警报把夜班警卫从浅睡中唤醒。','The alarm roused the guard / from a light sleep / before the gate opened.','rouse.s1 指使睡着的人醒来。','警报使警卫从睡梦中醒来。'),C('rouse.s2','激起；使振奋','The coach’s speech roused the tired players to defend their lead during the final minutes.','教练的讲话激励疲惫的球员在最后几分钟守住领先优势。','The coach’s speech roused the players / to defend their lead / in the final minutes.','rouse.s2 指激起某人的情绪、行动或兴奋感。','讲话激发球员继续努力。')],M('The alarm roused the guard by keeping him asleep and preventing him from hearing the signal.','The alarm roused the guard by waking him from his light sleep.','让警卫继续睡着不是唤醒。','meaning'),[q('What roused the night guard?','the alarm','a chess rook','the weekly rota','警报把夜班警卫从浅睡中唤醒。',1,'context'),q('What did the coach’s speech encourage the players to do?','defend their lead','go to sleep before the match','round the central island','讲话激励球员在比赛最后阶段守住领先。',2,'context'),q('What does rouse mean in the alarm sentence?','wake someone from sleep','make someone feel excited','route a shipment','第一句中 rouse 指把人从睡眠中叫醒。',1,'meaning'),q('What does rouse mean in the coach sentence?','stir someone to action or excitement','wake someone from sleep only','make a surface uneven','教练的讲话 roused 球员，意为激发他们继续行动。',2,'meaning')]);
P('rout','Rout comes through French route in the sense of a defeated, broken force; as a noun it is a disorderly defeat, and as a verb it means defeat utterly and force flight.',[C('rout.s1','溃败','The visiting team suffered a rout after its opponents scored seven unanswered goals in the second half.','客队在下半场被对手连进七球，遭遇惨败。','The visiting team suffered a rout / after seven unanswered goals / in the second half.','rout.s1 指一方被彻底击败并溃散的败局。','连续失球导致客队惨败。'),C('rout.s2','击溃；使溃逃','The defenders routed the invading force and forced its soldiers to flee across the border.','守军击溃入侵部队，迫使士兵越境逃跑。','The defenders routed the invading force / and forced soldiers / to flee.','rout.s2 作动词，指彻底击败并迫使对方逃散。','守军击败入侵者并令其溃逃。')],M('The visiting team suffered a rout after it won by seven goals and its opponents left the field defeated.','The visiting team suffered a rout after its opponents defeated it by seven unanswered goals.','大胜对手不属于遭遇惨败。','meaning'),[q('Why did the visiting team suffer a rout?','the opponents scored seven unanswered goals','the visitors won by seven goals','the game ended before play began','客队被连进七球，遭遇惨败。',1,'context'),q('What did the defenders force the invading soldiers to do?','flee across the border','join the rota','round the station','守军击溃入侵部队并迫使士兵逃跑。',2,'context'),q('What does rout mean as a noun?','a complete, disorderly defeat','a circular traffic junction','a regular work schedule','rout 作名词指彻底溃败。',1,'meaning'),q('What does rout mean as a verb?','defeat utterly and force to flee','plan a route on a map','wake a guard from sleep','rout 作动词指击溃并迫使对方逃散。',2,'meaning')]);
P('route','Route came through Old French route, from Latin rupta via (“broken way”); it can mean a path, a method of achieving something, or send goods/data along a chosen path.',[C('route.s1','路线；航线','The hikers chose a coastal route that passes three lighthouses before reaching the harbor.','徒步者选择了一条海岸路线，途中经过三座灯塔后抵达港口。','The hikers chose a coastal route / passing three lighthouses / before the harbor.','route.s1 指从一地到另一地所走的道路或航线。','徒步者按海岸路线行进。'),C('route.s2','途径；渠道','A grant from the foundation offered the small museum a route to fund its roof repairs.','基金会的拨款为这家小博物馆提供了筹集屋顶维修资金的途径。','The grant offered the museum a route / to fund / its roof repairs.','route.s2 可比喻实现目标的方法或途径。','拨款成为解决维修资金问题的渠道。'),C('route.s3','按路线发送；给……规定路线','The server routes each emergency call to the nearest available dispatcher.','服务器将每个紧急呼叫转接给最近的空闲调度员。','The server routes each emergency call / to the nearest / available dispatcher.','route.s3 作动词，指按特定路径发送货物、数据或呼叫。','系统按位置转接来电。')],M('The hikers followed a route to the harbor by walking away from the coast and never reaching the destination.','The hikers followed the coastal route past three lighthouses and arrived at the harbor.','没有沿路线抵达目的地不符合按路线前往的意思。','meaning'),[q('What did the coastal route pass?','three lighthouses','three roundabouts','three dormitory rooms','徒步路线经过三座灯塔后抵达港口。',1,'context'),q('How did the grant help the museum?','it provided a way to fund roof repairs','it routed emergency calls','it turned the roof into a round shape','拨款为博物馆维修屋顶提供了途径。',2,'context'),q('Where does the server route each emergency call?','to the nearest available dispatcher','to the museum’s roof','to the coastal lighthouse','服务器把紧急呼叫转接给最近的空闲调度员。',3,'context'),q('Which use of route means “a method of achieving something”?','a route to fund roof repairs','a route passing three lighthouses','the server routes a call','第一句中的 route 指实现目标的途径。',1,'meaning')]);
P('routine','Routine came through French routine, related to route and a customary course; it can mean a regular series of activities, regularly done, or ordinary and boring.',[C('routine.s1','常规；日常安排','Her morning routine includes stretching, feeding the cat, and checking the train schedule.','她的晨间日常安排包括拉伸、喂猫和查看列车时刻表。','Her morning routine includes / stretching, feeding the cat, / and checking the schedule.','routine.s1 指按固定时间重复进行的一系列事情。','晨间活动形成固定习惯。'),C('routine.s2','例行的；常规的','A routine inspection found a loose bolt but no serious damage to the bridge.','一次例行检查发现一颗螺栓松动，但桥梁没有严重损坏。','A routine inspection found / a loose bolt / but no serious damage.','routine.s2 作形容词，表示经常进行、没有特殊原因的。','检查按常规安排进行。'),C('routine.s3','平淡的；乏味的','After months of identical shifts, the warehouse work began to feel routine and uninteresting.','连续数月轮值完全相同后，仓库工作开始显得平淡乏味。','The warehouse work felt routine / after months / of identical shifts.','routine.s3 指因一直没有变化而普通、乏味。','相同轮班让工作变得单调。')],M('Her morning routine was a sequence she had never repeated and did not do at a regular time.','Her morning routine was the set of activities she repeated each day.','从不重复且没有固定时间，不符合 routine 的日常安排义。','meaning'),[q('What is part of her morning routine?','stretching and feeding the cat','inspecting the bridge every year','routing emergency calls','她的晨间安排包括拉伸和喂猫。',1,'context'),q('What did the routine bridge inspection find?','a loose bolt and no serious damage','a complete collapse','a new coastal route','例行检查发现一颗螺栓松动，但没有严重损坏。',2,'context'),q('Why did warehouse work feel routine?','the shifts were identical for months','each day brought a new activity','the crew stayed in a roundabout','轮班连续数月相同，使工作显得单调。',3,'context'),q('Which use of routine means “ordinary and boring”?','the work began to feel routine','her morning routine includes stretching','a routine inspection took place','最后一句中 routine 指平淡乏味的。',3,'meaning')]);
P('routinely','Routinely is formed from routine and -ly; it means as part of an established routine and therefore often.',C('routinely.s1','例行地；经常地','The technician routinely checks the pressure gauge at the start of every shift.','技师每个班次开始时都会例行检查压力表。','The technician routinely checks the gauge / at the start / of every shift.','routinely 修饰动作，表示按惯例经常进行。','检查是每班固定步骤。'),M('The technician routinely checked the gauge once in a lifetime and never as part of any repeated schedule.','The technician routinely checked the gauge at the start of each shift.','一生只检查一次并非按惯例经常检查。','meaning'),[q('When does the technician routinely check the gauge?','at the start of every shift','only after the machine breaks','once in a lifetime','技师每个班次开始都会检查压力表。',1,'context'),q('What does routinely mean?','as part of a regular practice and often','unexpectedly and only once','in a circular motion','routinely 表示按惯例经常进行。',1,'meaning'),q('Which action is done routinely?','a nurse recording each patient’s temperature every morning','a visitor checking a gauge one time ever','a driver choosing a route at random','护士每天早上记录体温属于例行工作。',1,'context'),q('What word is routinely formed from?','routine','roughness','rotary','routinely 由 routine 加 -ly 构成。',1,'word-formation')]);
P('routinist','Routinist combines routine and -ist; it means a person who prefers fixed routines and resists change.',C('routinist.s1','墨守成规的人','As a routinist, Mr. Hale opposed changing the meeting time even when the old schedule excluded several workers.','作为一个墨守成规的人，黑尔先生反对更改会议时间，即使旧安排让几名员工无法参加。','As a routinist, Mr. Hale opposed a schedule change / even when / workers were excluded.','routinist 指偏爱固定惯例、抗拒改变的人。','他坚持旧时间安排。'),M('Mr. Hale was a routinist because he welcomed constant changes and disliked following any fixed schedule.','Mr. Hale was a routinist because he preferred keeping the old meeting schedule unchanged.','喜欢不断改变且厌恶固定安排，与 routinist 的含义相反。','meaning'),[q('What change did Mr. Hale oppose?','changing the meeting time','checking the pressure gauge','rounding a road bend','黑尔先生反对更改会议时间。',1,'context'),q('Why did he resist changing the schedule?','he preferred fixed routines','he wanted every meeting to move randomly','he disliked having any routine','作为 routinist，他偏爱固定惯例并抗拒改变。',1,'context'),q('What is a routinist?','someone who prefers fixed routines and resists change','someone who studies the roots of plants','someone who moves a rook in chess','routinist 指偏爱固定惯例的人。',1,'meaning'),q('Which word does routinist contain?','routine','route','roost','routinist 由 routine 加 -ist 构成。',1,'word-formation')]);
P('routinization','Routinization is formed from routine and -ization; it names the process of making a practice regular and almost automatic.',C('routinization.s1','常规化','The routinization of the safety check meant that workers inspected the valves at the same point in every shift.','安全检查常规化后，工人每班都在同一环节检查阀门。','The routinization of the safety check meant / workers inspected valves / each shift.','routinization 指把做法变成固定惯例、减少临时决定的过程。','阀门检查成为每班固定步骤。'),M('The routinization of the safety check meant workers inspected the valves only once and never followed a repeated process.','The routinization of the safety check made valve inspection a regular step in every shift.','只做一次且不重复，不是把检查常规化。','meaning'),[q('What became routine in the factory?','inspecting valves during every shift','changing the meeting time each day','routing each call to a new city','工人每班固定检查阀门，说明安全检查常规化。',1,'context'),q('What does routinization mean?','making a practice regular and nearly automatic','removing every repeated practice','making a surface rough','routinization 指把做法变成固定惯例的过程。',1,'meaning'),q('Which change is routinization?','a clinic adopts the same opening checklist each morning','workers decide from scratch each day whether to check safety','a driver rounds a bend once','诊所每天采用固定开门检查清单属于常规化。',1,'context'),q('Which verb is routinization related to?','routinize','rout','rouse','routinization 与 routinize（使惯例化）相关。',1,'word-formation')]);
P('routinize','Routinize combines routine and -ize; it means establish an activity as a regular, nearly automatic procedure.',C('routinize.s1','使惯例化','The clinic decided to routinize handwashing checks so every room was inspected before patients arrived.','诊所决定把洗手检查固定为常规流程，在病人到来前检查每个房间。','The clinic decided to routinize checks / so every room / was inspected before arrival.','routinize 指把活动确立为定期、近乎自动的程序。','检查纳入每日固定流程。'),M('The clinic routinized the check by making it a one-time event that nobody repeated or scheduled.','The clinic routinized the check by adding it as a regular step before patients arrived.','一次性且不安排重复的事件不是惯例化流程。','meaning'),[q('When did staff inspect rooms after the clinic routinized checks?','before patients arrived','only once after the clinic closed','during a chess match','诊所把洗手检查设为病人到来前的固定步骤。',1,'context'),q('What does routinize mean?','establish an activity as a regular procedure','make an activity unpredictable','estimate something approximately','routinize 指把活动固定为常规程序。',1,'meaning'),q('Which workplace action is routinized?','workers use the same checklist at the start of every shift','workers invent a new checklist each minute','workers skip all safety checks','每班使用同一清单属于惯例化。',1,'context'),q('Which suffix turns routine into the verb routinize?','-ize','-less','-age','routine 加 -ize 构成动词 routinize。',1,'word-formation')]);
P('row','Row has distinct homonymous histories: the noun for a line comes from Old English rǣw, the rowing verb from Old English rāwan, and the argument sense has uncertain origins.',[C('row.s1','一排；一行','A row of lanterns lined the path from the gate to the riverside stage.','从大门到河边舞台的小路两侧排着一行灯笼。','A row of lanterns lined the path / from the gate / to the riverside stage.','row.s1 指彼此相邻排列成线的人或物。','灯笼沿小路排成一行。'),C('row.s2','划船','The two students rowed across the lake before the wind pushed their boat toward shore.','风把小船吹向岸边前，两名学生划船横渡了湖面。','The two students rowed across the lake / before the wind / pushed them shoreward.','row.s2 作动词，指用桨划船前进。','学生用桨划过湖面。'),C('row.s3','争吵；吵架','A row broke out between the neighbors over the loud music after midnight.','午夜后因音乐太吵，邻居之间爆发了争吵。','A row broke out between the neighbors / over loud music / after midnight.','row.s3 指激烈而吵闹的争论。','邻居因音乐问题吵了起来。')],M('A row of lanterns lined the path in a scattered pattern, with each lantern placed far from any other.','A row of lanterns lined the path in a straight line with each lantern beside the next.','分散摆放而不成线，不是一排。','meaning'),[q('What lined the path to the riverside stage?','a line of lanterns','two students in a boat','neighbors arguing after midnight','一排灯笼沿小路通向河边舞台。',1,'context'),q('What did the two students do across the lake?','rowed their boat with oars','argued over music','stood in a row of lanterns','两名学生用桨划船横渡湖面。',2,'context'),q('What started between the neighbors?','a noisy argument','a boat race','a line of lanterns','邻居因午夜后的音乐声爆发争吵。',3,'context'),q('Which use of row means a line?','a row of chairs beside the stage','the students rowed across the lake','a row broke out next door','第一句的 row 指排成线的一排椅子。',1,'meaning')]);
P('royal','Royal comes through Old French roial from Latin regalis, “kingly,” from rex (“king”); it can describe a monarch’s family, something grand, or a member of that family.',[C('royal.s1','王室的；皇家的','The royal residence opened its gardens to the public during the annual charity event.','年度慈善活动期间，王室住所向公众开放了花园。','The royal residence opened its gardens / to the public / during the charity event.','royal.s1 指属于或与国王、女王及其家族有关的。','王室住所举办公众开放活动。'),C('royal.s2','盛大的；庄严的','The orchestra gave the retiring conductor a royal farewell with a full choir and a procession of musicians.','乐团为退休指挥举行了盛大的告别仪式，有完整合唱团和乐手队伍。','The orchestra gave the conductor / a royal farewell / with a full choir.','royal.s2 可形容盛大、适合王室规格的场面。','告别仪式规模宏大。'),C('royal.s3','王室成员','A royal greeted the visiting children at the palace gate and answered their questions about the ceremony.','一位王室成员在宫殿门口迎接来访儿童，并回答他们关于典礼的问题。','A royal greeted the children / at the palace gate / and answered questions.','royal.s3 作名词，指国王或女王家族的成员。','一位王室成员接待来访儿童。')],M('The royal residence belonged to a private tenant with no connection to a king, queen, or royal family.','The royal residence belonged to the monarch’s family.','与王室毫无关系的私人租户住所不属于王室住所。','meaning'),[q('What did the royal residence open?','its gardens','the orchestra’s score','the children’s school room','王室住所向公众开放了花园。',1,'context'),q('What made the conductor’s farewell royal?','a full choir and a procession of musicians','one person leaving quietly','a rough estimate of the cost','乐团以合唱团和乐手队伍举行了盛大的告别。',2,'context'),q('Who greeted the children at the palace?','a member of the royal family','the retiring conductor','a private tenant','一位王室成员在宫殿门口接待儿童。',3,'context'),q('What does royal mean in “a royal residence”?','belonging to a monarch or royal family','large enough to hold a choir','a person who attends a ceremony','royal residence 指王室住所。',1,'meaning')]);
P('royalty','Royalty is formed from royal and -ty; it can mean money paid per copy or use, or members of a royal family collectively.',[C('royalty.s1','版税；稿酬','The novelist receives a royalty for every copy of her book sold through the publisher.','这位小说家每售出一本书，就从出版商那里获得一笔版税。','The novelist receives a royalty / for every copy / sold by the publisher.','royalty.s1 指按作品销售数量支付给作者或音乐人的报酬。','作者随销量获得版税。'),C('royalty.s2','专利许可费','The company pays a royalty to the inventor for every device made under the patented design.','公司按专利设计生产的每台设备向发明者支付许可费。','The company pays a royalty / for each device / made under the patent.','royalty.s2 指使用专利或资源所支付的费用。','专利使用按件付费。'),C('royalty.s3','皇室；王族','The visiting royalty stood on the palace balcony as the national parade passed below.','游行队伍经过时，来访王族成员站在宫殿阳台上。','The visiting royalty stood on the balcony / as the parade / passed below.','royalty.s3 指王室成员的集合或王族。','王族成员观看国家游行。')],M('The novelist received a royalty for each book even though the publisher paid her nothing for any copy sold.','The novelist received a royalty payment for each copy sold.','每本售出后都不支付报酬，不符合版税的含义。','meaning'),[q('What earns the novelist royalty payments?','each copy of her book sold','every hour she spends at the palace','each time a parade passes','小说家每售出一本书就能获得版税。',1,'context'),q('Why does the company pay the inventor?','it uses the patented design in each device','the novelist sold a copy','the visiting family attended a parade','公司因使用专利设计而按设备支付许可费。',2,'context'),q('Who stood on the palace balcony?','the visiting members of a royal family','the company’s patent examiner','the novelist’s publisher','游行经过时，来访王族成员站在宫殿阳台上。',3,'context'),q('Which use of royalty means money paid for a work’s sales?','the author earns royalty on each book','the royalty watched the parade','the patent royalty covers each device','第一句中的 royalty 指作者获得的版税。',1,'meaning')]);
P('rub','Rub is recorded in Middle English with the sense of moving back and forth while pressing; its deeper origin is uncertain, and it can also name friction or an obstacle.',[C('rub.s1','摩擦；擦；揉','Rub the damp cloth over the glass in small circles to remove the fingerprints.','用湿布在玻璃上画小圈擦拭，去掉指纹。','Rub the damp cloth over the glass / in small circles / to remove fingerprints.','rub.s1 指按压表面并来回移动手或物体。','湿布在玻璃上反复擦动。'),C('rub.s2','摩擦；阻碍','The only rub in the plan is that the delivery truck cannot reach the narrow street.','计划中唯一的难题是送货卡车无法驶入那条狭窄街道。','The only rub in the plan / is that the truck / cannot reach the street.','rub.s2 作名词可指摩擦，也可指使情况困难的问题。','卡车进不去是计划的障碍。')],M('She rubbed the glass by holding the cloth several inches away and never touching the surface.','She rubbed the glass by pressing the cloth against it and moving in small circles.','不接触表面就不会发生擦拭。','meaning'),[q('How should the cloth move over the glass?','in small circles','in a straight line across the street','around a royal palace','要用湿布在玻璃上画小圈擦拭。',1,'context'),q('What was the only rub in the delivery plan?','the truck could not reach the narrow street','the glass had fingerprints','the royal garden was open','唯一的难题是送货卡车进不了狭窄街道。',2,'context'),q('What does rub mean as a verb?','move something back and forth while pressing','move a truck along a route','assign a payment for each copy','动词 rub 指按压并来回擦动。',1,'meaning'),q('What does “the rub in the plan” mean?','the problem that makes it difficult','a cloth used to polish glass','a royal payment','the rub 指计划中造成困难的问题。',2,'meaning')]);
P('rub out','Rub out combines rub and out; it means remove writing or a mark from paper by rubbing it with an eraser or finger.',C('rub out.s1','擦掉；涂去','Please rub out the incorrect date on the form and write the corrected one in the same box.','请把表格上的错误日期擦掉，并在同一栏写上正确日期。','Please rub out the incorrect date / and write the correct one / in the same box.','rub out 指通过摩擦把纸上的字迹或标记去掉。','错误日期被擦去并改正。'),M('She rubbed out the pencil mark by drawing over it with a permanent marker and leaving the mark visible.','She rubbed out the pencil mark with an eraser until it disappeared.','用永久性记号笔覆盖并保留标记，不是擦除。','meaning'),[q('What should be removed from the form?','the incorrect date','the correct date after it is written','the entire box','表格上的错误日期应该擦掉。',1,'context'),q('What should be written after rubbing it out?','the corrected date','a royal title','a delivery route','擦掉错误日期后，要在同一栏写上正确日期。',1,'context'),q('What does rub out mean?','remove a mark by rubbing','write a new mark without removing anything','pay a fee for a design','rub out 指通过摩擦擦除标记。',1,'meaning'),q('Which tool can rub out a pencil mark?','an eraser','a patent license','a glass fingerprint','橡皮可以擦掉铅笔痕迹。',1,'context')]);
P('rubber','Rubber is formed from rub and -er; it names an elastic substance, a block used to erase pencil marks (especially British English), or something made of rubber.',[C('rubber.s1','橡胶','The rubber gasket flexes without cracking and keeps water from leaking around the pipe joint.','橡胶垫圈可以弯曲而不开裂，防止水从管道接头处漏出。','The rubber gasket flexes / without cracking / and seals the pipe joint.','rubber.s1 指具有弹性的材料，可由植物乳汁或化学方法制成。','橡胶垫圈用于密封接头。'),C('rubber.s2','橡皮；橡胶制品','In British English, Ella used a rubber to erase the pencil answer before handing in her worksheet.','在英式英语中，埃拉用橡皮擦掉铅笔答案后交上练习纸。','Ella used a rubber / to erase the pencil answer / before handing in the sheet.','rubber.s2 可指擦铅笔字的橡皮，也可泛指橡胶制品。','橡皮擦除了铅笔答案。'),C('rubber.s3','橡胶的','The workshop fitted rubber wheels to the cart so it would roll quietly over the tiled floor.','工坊给推车装上橡胶轮子，使它能安静地驶过瓷砖地面。','The workshop fitted rubber wheels / so the cart rolled / quietly over tile.','rubber.s3 作形容词，表示由橡胶制成的。','橡胶轮子降低噪音。')],M('The rubber gasket was brittle glass that cracked immediately and let water leak through the joint.','The rubber gasket was elastic and sealed the pipe joint without cracking.','易碎玻璃不能体现橡胶的弹性和密封作用。','meaning'),[q('What did the rubber gasket prevent?','water leaking around the pipe joint','the pencil answer being erased','the cart moving over the floor','橡胶垫圈防止水从管道接头漏出。',1,'context'),q('What did Ella use the rubber for?','erasing a pencil answer','sealing a water pipe','quieting the cart wheels','Ella 用橡皮擦掉铅笔答案。',2,'context'),q('Why were rubber wheels fitted to the cart?','to roll quietly over tile','to erase a worksheet','to stop the royal payment','橡胶轮子让推车安静地驶过瓷砖地面。',3,'context'),q('Which use of rubber is an adjective?','rubber wheels','a rubber for erasing','elastic rubber material','rubber wheels 中 rubber 作形容词，表示橡胶制的。',1,'meaning')]);
P('rubbery','Rubbery is formed from rubber and -y; it describes something elastic and tough like rubber, sometimes unpleasantly so.',C('rubbery.s1','橡胶似的；有弹性的','The overcooked noodles became rubbery, so the chef removed them from the menu.','面条煮过头后变得像橡胶一样韧，厨师便把它们从菜单上撤下。','The overcooked noodles became rubbery / so the chef / removed them from the menu.','rubbery 指像橡胶一样有弹性且坚韧，有时带有令人不快的感觉。','面条口感韧得像橡胶。'),M('The noodles were rubbery because they fell apart into a soft liquid with no elasticity or toughness.','The noodles were rubbery because they were tough and springy when chewed.','软烂成液体、没有弹性的食物不是 rubbery。','meaning'),[q('Why did the chef remove the noodles from the menu?','they had become tough and rubbery','they had been erased with a rubber','they were arranged in a rota','面条变得像橡胶一样韧，厨师把它们撤下。',1,'context'),q('What does rubbery describe?','elastic and tough like rubber','smooth and watery','round and easy to erase','rubbery 指像橡胶一样有弹性且坚韧。',1,'meaning'),q('Which food texture is rubbery?','an overcooked piece of meat that springs back when pressed','a tender vegetable that breaks easily','a bowl of thin soup','按压后回弹、过韧的肉有 rubbery 口感。',1,'context'),q('Which noun forms rubbery?','rubber','rubric','rubble','rubber 加 -y 构成形容词 rubbery。',1,'word-formation')]);
P('rubbing','Rubbing is formed from rub and -ing; it can mean friction/scraping sound or mark, and a copy made by rubbing paper over an inscription.',[C('rubbing.s1','摩擦声；擦痕','A faint rubbing from the wheel warned the mechanic that the brake pad was touching the rim.','车轮发出轻微摩擦声，提醒技师刹车片正碰到轮圈。','A faint rubbing from the wheel / warned the mechanic / about the brake pad.','rubbing.s1 指两个表面摩擦时发出的声音或留下的痕迹。','车轮摩擦声表明刹车片接触轮圈。'),C('rubbing.s2','拓片；摹拓','The historian made a rubbing of the carved date by placing thin paper over the stone and shading it with charcoal.','历史学家把薄纸覆在石刻上，用木炭拓印出日期。','The historian made a rubbing / by placing paper over the stone / and shading it.','rubbing.s2 指覆盖纸张后用铅笔或炭拓出图案或铭文。','石刻日期被拓印下来。')],M('The historian made a rubbing of the inscription by covering it with paper and never applying any pencil, chalk, or charcoal.','The historian made a rubbing by laying paper over the inscription and shading across it with charcoal.','不摩擦拓印介质就不能制成拓片。','meaning'),[q('What did the wheel’s faint rubbing tell the mechanic?','the brake pad touched the rim','the rubber gasket leaked water','the cart had a royal wheel','摩擦声提醒技师刹车片碰到了轮圈。',1,'context'),q('How did the historian copy the carved date?','by rubbing charcoal over paper placed on the stone','by photographing a rubber eraser','by rewriting the date from memory','历史学家用纸覆石刻，再用木炭摩擦拓印。',2,'context'),q('What does rubbing mean in the wheel example?','a friction sound or mark','a copy made from a carved design','a formal work schedule','这里 rubbing 指摩擦声。',1,'meaning'),q('What is a rubbing in the historian example?','a copy of an inscription made by rubbing over paper','a sound from a brake pad','a rubber object used to erase a mark','此处 rubbing 指用摩擦方法制成的石刻拓片。',2,'meaning')]);
P('rubbish','Rubbish has uncertain deeper origins; it means discarded waste, nonsense/poor-quality material, or (as a verb) speak dismissively about something.',[C('rubbish.s1','垃圾；废弃物','The volunteers collected rubbish from the riverbank and sorted bottles from food wrappers.','志愿者清理河岸垃圾，并把瓶子和食品包装分开。','The volunteers collected rubbish / and sorted bottles / from food wrappers.','rubbish.s1 指被丢弃、不再需要的东西。','志愿者收集并分类废物。'),C('rubbish.s2','废话；胡说；劣质品','The reviewer called the claim that the bridge could float “rubbish” because no evidence supported it.','评论者称“桥能漂浮”的说法是胡说，因为没有证据支持。','The reviewer called the claim rubbish / because no evidence / supported it.','rubbish.s2 可指荒唐错误的话或质量极差的东西。','没有证据的说法被斥为胡说。'),C('rubbish.s3','贬低；说……一文不值','The critic rubbished the proposal in the newspaper, arguing that it would waste public funds.','评论家在报纸上贬低这项提案，认为它会浪费公共资金。','The critic rubbished the proposal / in the newspaper / as wasteful.','rubbish.s3 作动词，指说某事很糟或毫无价值。','评论家公开批评提案。')],M('The volunteers collected rubbish from the riverbank by adding more bottles and wrappers to the water.','The volunteers collected rubbish from the riverbank by removing discarded bottles and wrappers.','把更多废物扔进河里不是清理垃圾。','meaning'),[q('Where did volunteers collect rubbish?','from the riverbank','from the royal palace','from the chess file','志愿者在河岸清理垃圾。',1,'context'),q('Why did the reviewer call the floating-bridge claim rubbish?','no evidence supported it','the riverbank had been cleaned','the proposal included public funding','评论者认为该说法没有证据支持，是胡说。',2,'context'),q('What did the critic do to the proposal?','dismissed it publicly as worthless','collected it from the river','made a rubbing of its title','评论家在报纸上贬低了提案。',3,'context'),q('What does rubbish mean as a noun in “that claim is rubbish”?','nonsense or something of very poor quality','discarded household waste only','a critic’s act of public attack','这里 rubbish 指荒唐无稽的话。',1,'meaning')]);
P('rubble','Rubble has an uncertain deeper history and names broken stone, brick, or concrete left after a building collapses.',C('rubble.s1','碎石；瓦砾','Rescue workers searched the rubble of the collapsed school for anyone still trapped beneath the bricks.','救援人员在倒塌学校的瓦砾中搜寻是否还有人被困在砖块下。','Rescue workers searched the rubble / for anyone trapped / beneath the bricks.','rubble 指建筑物倒塌后留下的破碎石块、砖块或混凝土。','救援人员在废墟中搜救。'),M('Rescue workers searched the rubble even though the school was intact and no stones, bricks, or concrete had fallen.','Rescue workers searched the broken bricks and concrete left by the collapsed school.','建筑物完好无损且没有碎块时，不存在瓦砾。','meaning'),[q('What were rescue workers searching for in the rubble?','people trapped beneath the bricks','a royal family’s jewels','an erased pencil mark','救援人员在学校瓦砾中寻找被困者。',1,'context'),q('What can rubble contain?','broken stone, brick, and concrete','fresh vegetables and whole grains','paper with a copied inscription','rubble 指建筑倒塌后留下的碎石砖块。',1,'meaning'),q('What created the rubble at the school?','the building collapsed','workers polished its floors','a rooster entered the room','学校倒塌后留下瓦砾。',1,'context'),q('Which site is covered in rubble?','a collapsed building’s broken masonry','a newly built smooth floor','a field of rice seedlings','倒塌建筑的碎砖和石块构成 rubble。',1,'context')]);
P('rubric','Rubric comes from Latin rubrica, “red earth” or a red heading, from ruber (“red”); it means a rule, heading, or guide for doing or judging something.',C('rubric.s1','规程；评分量规','The teacher shared a rubric that listed the criteria for clarity, evidence, and organization in each essay.','老师发了一份评分量规，列出每篇文章在清晰度、证据和组织方面的标准。','The teacher shared a rubric / listing criteria / for each essay.','rubric 指说明如何完成或评价任务的规则、标题或指南。','量规列明作文评分标准。'),M('The teacher graded the essays with a rubric but gave no criteria and changed the standards secretly for each student.','The teacher graded the essays with a rubric that stated the same criteria for everyone.','没有标准且对每人暗改要求，不符合量规提供评价指南的作用。','meaning'),[q('What criteria did the essay rubric list?','clarity, evidence, and organization','color, rhythm, and room size','the route and rota','量规列出清晰度、证据和组织等评分标准。',1,'context'),q('What is a rubric?','a guide for doing or judging something','a discarded piece of building material','an elastic substance','rubric 是用于完成或评价工作的指南。',1,'meaning'),q('How did the teacher make grading fair?','used the same stated criteria for each student','changed requirements secretly for each essay','graded without reading the work','老师对每篇文章使用相同公开标准，评分更公平。',1,'context'),q('Which Latin word is related to rubric?','rubrica, “red earth” or a red heading','rosa, “rose”','rūm, “space”','rubric 源自拉丁语 rubrica，原指红土或红色标题。',1,'word-formation')]);
P('ruby','Ruby came through Old French rubi from Latin rubinus, related to rubeus (“red”); it can mean the precious red stone, its deep-red color, or that color itself.',[C('ruby.s1','红宝石','The jeweler examined the ruby under a lamp to check for cracks before setting it in a ring.','珠宝商在把红宝石镶进戒指前，在灯下检查是否有裂纹。','The jeweler examined the ruby / under a lamp / before setting it in a ring.','ruby.s1 指用于珠宝的珍贵深红色宝石。','珠宝商检查红宝石的裂纹。'),C('ruby.s2','深红色','The sunset left a ruby glow along the western clouds above the harbor.','日落时，港口上方西边的云层泛起深红色光辉。','The sunset left a ruby glow / along the western clouds / above the harbor.','ruby.s2 可指像红宝石一样浓郁的深红色。','云层呈现红宝石般的深红色。'),C('ruby.s3','红宝石色的','She chose a ruby necklace to match the deep red fabric of her evening dress.','她选了一条红宝石色项链，搭配晚礼服的深红布料。','She chose a ruby necklace / to match / her deep red dress.','ruby.s3 作形容词，指具有红宝石的深红色。','项链与礼服颜色相配。')],M('The jeweler called the transparent green stone a ruby even though it was not red and had no ruby identity.','The jeweler called the deep-red precious stone a ruby.','绿宝石不是红宝石。','meaning'),[q('What did the jeweler check before setting the ruby?','whether it had cracks','whether it smelled sour','whether it could be rubbed out','珠宝商检查红宝石是否有裂纹。',1,'context'),q('What color glow did the sunset leave?','deep ruby red','pale blue','bright green','日落使西边云层泛起深红光辉。',2,'context'),q('What does ruby describe in “a ruby necklace”?','the necklace’s deep-red color','the stone’s value only','the jeweler’s tool','ruby necklace 中 ruby 描写项链的深红色。',3,'context'),q('Which use of ruby names the gemstone itself?','the jeweler examined the ruby','the clouds had a ruby glow','she chose a ruby necklace','第一句中的 ruby 指红宝石这种宝石。',1,'meaning')]);
P('ruddy','Ruddy is from Old English rudig, related to rudu (“redness”); it can describe a healthy red face or serve as an informal intensifier for an unpleasant or complete thing.',[C('ruddy.s1','红润的；红扑扑的','After working outside in the cold, the farmer came indoors with a ruddy face and warm hands.','在寒冷的户外工作后，农夫走进屋时脸颊红润，双手温暖。','The farmer came indoors with a ruddy face / after working / in the cold.','ruddy.s1 描写脸色健康发红。','农夫的脸颊因户外活动而泛红。'),C('ruddy.s2','（英口）讨厌的；十足的','The ruddy alarm went off again at midnight, waking the entire household.','那该死的闹钟午夜又响了，把全家人都吵醒。','The ruddy alarm went off again / at midnight / waking everyone.','ruddy.s2 在英式口语中用作强调词，表达不满或加强语气。','说话者不满闹钟再次响起。')],M('The farmer had a ruddy face because his skin was pale gray and showed no healthy color.','The farmer had a ruddy face with a healthy red color after working outside.','苍白灰暗的脸不是红润的。','meaning'),[q('Why did the farmer have a ruddy face?','he had worked outside in the cold','the alarm woke the household','he handled rotten peaches','农夫在寒冷户外工作后脸颊红润。',1,'context'),q('What did the ruddy alarm do?','went off again at midnight','turned deep red at sunrise','was rubbed out from a form','说话者不满闹钟午夜又响。',2,'context'),q('What does ruddy describe about the farmer?','his healthy red complexion','his anger at the alarm','his daily routine','ruddy face 指健康红润的脸色。',1,'meaning'),q('How is ruddy used before “alarm” in the second example?','as an informal word emphasizing annoyance','as a literal color description only','as a name for a gemstone','ruddy 在 alarm 前是表达不满的口语强调词。',2,'meaning')]);
P('rude','Rude comes from Latin rudis, “rough or untrained,” through French; it can mean impolite, sudden and unpleasant, or made in a simple rough way.',[C('rude.s1','粗鲁的；无礼的','It was rude to interrupt the speaker before she had finished explaining the safety rules.','在演讲者解释完安全规则前打断她是不礼貌的。','It was rude to interrupt the speaker / before she had finished / explaining the rules.','rude.s1 指不礼貌、可能冒犯他人的。','打断讲话显得无礼。'),C('rude.s2','突如其来的；猛烈的','The hikers woke to a rude gust of wind that knocked the empty tent against a tree.','徒步者被一阵突如其来的强风惊醒，空帐篷被吹得撞上树。','The hikers woke to a rude gust / that knocked the tent / against a tree.','rude.s2 可形容突然且令人不快的事物。','突发强风把帐篷吹向树。'),C('rude.s3','粗制的；简陋的','The travelers built a rude shelter from branches and leaves before the rain started.','下雨前，旅客用树枝和树叶搭起一座简陋的避雨棚。','The travelers built a rude shelter / from branches and leaves / before the rain.','rude.s3 指制作简单、粗糙的。','树枝和树叶搭成简易棚子。')],M('It was rude to interrupt the speaker because she had already finished, invited questions, and asked the audience to speak.','It was rude to interrupt the speaker while she was still explaining the safety rules.','在讲话者尚未说完时打断她才是不礼貌，原句所述场景已允许发言。','meaning'),[q('Why was interrupting the speaker considered rude?','she had not finished explaining the rules','she had invited everyone to interrupt','she was building a shelter','打断尚未说完的安全说明显得无礼。',1,'context'),q('What woke the hikers?','a sudden, unpleasant gust of wind','a polite question from the speaker','a deep-red gemstone','突如其来的强风把徒步者惊醒。',2,'context'),q('What kind of shelter did travelers build?','a simple shelter from branches and leaves','a polished stone hall','a fully furnished apartment','旅客用树枝树叶搭起简陋避雨棚。',3,'context'),q('What does rude mean in the phrase “a rude gust”?','sudden and unpleasant','impolite toward a speaker','carefully and professionally made','rude gust 指突如其来且令人不快的强风。',2,'meaning')]);
P('rudely','Rudely is formed from rude and -ly; it means in an impolite manner or, in another use, suddenly and unexpectedly.',[C('rudely.s1','粗鲁地；无礼地','The customer spoke rudely to the cashier and refused to let her finish answering.','顾客粗鲁地对收银员说话，不让她把回答说完。','The customer spoke rudely / and refused / to let the cashier finish.','rudely.s1 表示以不礼貌或不尊重的方式。','顾客打断收银员并无礼地讲话。'),C('rudely.s2','突兀地；出乎意料地','The hikers were awakened rudely by a sudden crash from the empty tent outside.','帐篷外突然传来一声巨响，徒步者被猛然惊醒。','The hikers were awakened rudely / by a sudden crash / from outside.','rudely.s2 指突然且令人不快地发生。','突发巨响打断了睡眠。')],M('The customer spoke rudely by listening patiently, thanking the cashier, and never interrupting her.','The customer spoke rudely by interrupting the cashier and using disrespectful language.','耐心倾听并致谢不是粗鲁地说话。','meaning'),[q('How did the customer treat the cashier?','interrupted her and spoke disrespectfully','let her finish and thanked her','invited her to a royal ceremony','顾客打断收银员并无礼地说话。',1,'context'),q('What woke the hikers rudely?','a sudden crash outside the tent','a quiet routine inspection','a pink-red ribbon','帐篷外突然的巨响把徒步者惊醒。',2,'context'),q('What does rudely mean in the customer example?','in an impolite manner','unexpectedly with a loud sound','in a circular route','顾客语境中的 rudely 指无礼地。',1,'meaning'),q('What does rudely mean in the hikers example?','suddenly and unpleasantly','with careful respect','approximately','徒步者语境中的 rudely 指突然且令人不快地。',2,'meaning')]);
P('rudimentary','Rudimentary comes from Latin rudimentum, “beginning,” from rudis (“rough or untrained”); it can mean basic and early-stage or underdeveloped in an organ.',[C('rudimentary.s1','初步的；基本的','The remote clinic has rudimentary equipment, including a thermometer, bandages, and a small first-aid kit.','偏远诊所只有一些基本设备，包括体温计、绷带和小型急救包。','The clinic has rudimentary equipment / including a thermometer / and basic supplies.','rudimentary.s1 指处于简单早期阶段、尚未完善的。','诊所配备的器材有限而基础。'),C('rudimentary.s2','（器官）退化的','In some cave fish, rudimentary eyes remain beneath the skin but do not form useful images.','某些洞穴鱼皮肤下仍有退化的眼睛，但无法形成有用图像。','Rudimentary eyes remain beneath the skin / but do not form / useful images.','rudimentary.s2 指生物器官未充分发育或功能不完善。','洞穴鱼的眼睛发育不完全。')],M('The clinic had rudimentary equipment, including a fully staffed surgical suite and every advanced imaging machine.','The clinic had rudimentary equipment, limited to basic first-aid supplies.','先进而齐全的设备不属于 rudimentary。','meaning'),[q('What equipment did the remote clinic have?','a thermometer, bandages, and a basic first-aid kit','a full surgical suite and advanced scanners','a roundabout and a rook','偏远诊所只有体温计、绷带等基础设备。',1,'context'),q('What is true of cave fish rudimentary eyes?','they remain under the skin and form no useful images','they provide sharper images than other fish eyes','they are made of rubber','洞穴鱼的退化眼睛不能形成有用图像。',2,'context'),q('What does rudimentary mean about equipment?','basic and not highly developed','complete and advanced','richly decorated','rudimentary equipment 指基本、尚不完善的设备。',1,'meaning'),q('What does rudimentary mean about an organ?','underdeveloped and not fully functional','a simple tool for a clinic','a very rude person','rudimentary eyes 指发育不完全、功能有限的眼睛。',2,'meaning')]);
P('rudiments','Rudiments is the plural of rudiment, from Latin rudimentum (“beginning”); it means basic principles to learn first or early forms not yet fully developed.',[C('rudiments.s1','基础知识；入门','Before joining the debate team, Omar studied the rudiments of argument: claims, evidence, and rebuttals.','加入辩论队前，奥马尔学习了论证的基础知识：主张、证据和反驳。','Omar studied the rudiments of argument / claims, evidence, / and rebuttals.','rudiments.s1 指继续深入学习前必须掌握的基础原则。','辩论入门包括论点、证据和反驳。'),C('rudiments.s2','雏形；未充分发展的形式','The first rudiments of a new leaf appeared at the tip of the seedling after a week of warm weather.','温暖天气持续一周后，幼苗顶端出现了新叶的雏形。','The first rudiments of a leaf appeared / at the seedling tip / after warm weather.','rudiments.s2 指已经出现但尚未充分发展的初步形式。','幼苗上出现新叶雏形。')],M('Omar learned the rudiments of debate by skipping all basic principles and studying only advanced legal theory.','Omar learned the rudiments of debate by starting with claims, evidence, and rebuttals.','跳过所有基础原则不属于学习入门知识。','meaning'),[q('What debate concepts did Omar study first?','claims, evidence, and rebuttals','advanced legal theory only','the route around the lake','奥马尔先学论证的基本组成部分。',1,'context'),q('Where did the first leaf rudiments appear?','at the tip of the seedling','inside the hotel room','on the chess rook','新叶雏形出现在幼苗顶端。',2,'context'),q('What are the rudiments of a subject?','its basic principles learned first','its final and most advanced theories','a set of daily duties','rudiments 指某学科的基础知识。',1,'meaning'),q('What does rudiments mean in “rudiments of a leaf”?','an early form not fully developed','basic principles for an argument','a fully grown leaf','rudiments of a leaf 指尚未充分发展的叶片雏形。',2,'meaning')]);
P('rue','Rue has separate histories: the regret verb and noun come from Old English hrēowan, while the plant name comes through Latin ruta from Greek rhute.',[C('rue.s1','后悔；懊悔','You may rue the decision to ignore the weather warning when the storm reaches the campsite.','暴风雨抵达营地时，你可能会后悔忽视天气警报的决定。','You may rue the decision / to ignore the warning / when the storm arrives.','rue.s1 作动词，指为过去做过的事感到后悔。','忽视警告可能让人后悔。'),C('rue.s2','悔恨；遗憾','Her only rue was that she had not thanked the volunteers before they left.','她唯一的遗憾是志愿者离开前没能向他们道谢。','Her only rue was / that she had not thanked / the volunteers before they left.','rue.s2 作名词，指对过去的悲伤和懊悔。','她为没及时道谢而遗憾。'),C('rue.s3','蓼；芸香类植物','The gardener planted rue with small yellow flowers beside the herb bed, following an old medicinal tradition.','园丁按照古老的药用传统，在香草畦旁种下开小黄花的芸香。','The gardener planted rue / with small yellow flowers / beside the herb bed.','rue.s3 指一种有小黄花、过去曾作药用的植物。','园丁在香草畦旁种下芸香。')],M('He rued ignoring the warning even though the storm never came and the campsite remained perfectly safe.','He rued ignoring the warning when the storm flooded the campsite.','如果没有发生不良后果，这句话不能说明他因忽视警告而后悔。','meaning'),[q('What decision might the camper rue?','ignoring the weather warning','planting a yellow-flowered herb','thanking volunteers before they left','营地遭遇风暴时，忽视警报的决定可能让人后悔。',1,'context'),q('What was her only rue?','she failed to thank the volunteers before they left','she planted too many flowers','she ignored a chess rota','她遗憾没有在志愿者离开前道谢。',2,'context'),q('Which plant did the gardener put beside the herb bed?','rue with small yellow flowers','a red ruby tree','a thorny rose with no flowers','园丁种的是开小黄花的芸香。',3,'context'),q('Which use of rue means regret?','He will rue ignoring the warning.','She planted rue in the garden.','Her only rue was a missed thank-you.','第一句中的 rue 是动词“后悔”。',1,'meaning')]);
P('ruffian','Ruffian came through Italian ruffiano, originally a violent or disreputable man; its deeper origin is uncertain. It can name such a person or describe violent, cruel behavior.',[C('ruffian.s1','恶棍；无赖','A ruffian threatened the shopkeeper and smashed the window when she refused to hand over the cash.','店主拒绝交出现金后，一个恶棍威胁她并砸碎了窗户。','A ruffian threatened the shopkeeper / and smashed the window / over the cash.','ruffian.s1 指使用暴力对待他人的粗暴男子。','恶棍以暴力威胁店主。'),C('ruffian.s2','凶恶的；暴戾的','The film portrays a ruffian gang whose cruel behavior frightens the residents of the port district.','影片描绘了一伙凶恶的团伙，他们的残暴行为吓坏了港区居民。','The film portrays a ruffian gang / whose cruel behavior / frightens residents.','ruffian.s2 作形容词，描述暴力、残忍的行为。','团伙行为凶残，使居民害怕。')],M('The ruffian protected the shopkeeper by politely returning the cash and repairing the window he had broken.','The ruffian threatened the shopkeeper and smashed her window.','礼貌归还钱款并修窗不是恶棍的暴力行为。','meaning'),[q('What did the ruffian do when the shopkeeper refused?','threatened her and smashed the window','returned the cash politely','offered to repair the roof','恶棍威胁店主并砸碎窗户。',1,'context'),q('What frightened port residents in the film?','the gang’s cruel behavior','a ruddy face','a rotational schedule','凶恶团伙的残暴行为吓坏了港区居民。',2,'context'),q('What is a ruffian?','a brutal person who uses violence','a person who learns by repetition','a person who shares a dorm room','ruffian 指使用暴力的恶棍。',1,'meaning'),q('What does ruffian mean as an adjective?','violent and cruel in behavior','deep red like a ruby','basic and early-stage','ruffian 作形容词指凶恶暴戾的。',2,'meaning')]);
P('ruffle','Ruffle has an uncertain deeper history; it can make a smooth surface untidy, disturb someone’s calm feelings, or name a gathered strip of decorative cloth.',[C('ruffle.s1','弄皱；弄乱','The wind ruffled the lake’s surface, breaking the reflection of the mountains into ripples.','风吹皱湖面，把山的倒影搅成一圈圈波纹。','The wind ruffled the lake / breaking the reflection / into ripples.','ruffle.s1 指使平滑表面变得不平或凌乱。','风吹皱平静的湖面。'),C('ruffle.s2','触怒；使不安','The reporter’s personal question ruffled the mayor, who paused before answering.','记者的私人问题让市长感到不安，他停顿片刻才回答。','The personal question ruffled the mayor / who paused / before answering.','ruffle.s2 指扰乱某人的平静情绪。','问题使市长不悦。'),C('ruffle.s3','褶边；皱褶','A white ruffle along the collar gave the plain blouse a decorative edge.','衣领边的一圈白色褶边为素色衬衫增添了装饰。','A white ruffle along the collar / gave the blouse / a decorative edge.','ruffle.s3 作名词，指衣服上的抽褶装饰布条。','衬衫衣领饰有白色褶边。')],M('The wind ruffled the lake by keeping its surface perfectly smooth and preserving an unbroken reflection.','The wind ruffled the lake by disturbing its surface and making small ripples.','水面完全平静、倒影未变，不符合 ruffle 的弄皱义。','meaning'),[q('What did the wind do to the lake’s surface?','broke the reflection into ripples','kept it perfectly smooth','covered it with a white cloth collar','风吹皱湖面，把倒影搅成波纹。',1,'context'),q('How did the reporter’s question affect the mayor?','it unsettled him','it gave him a ruby','it made him rouse the guard','私人问题让市长不安，回答前停顿了。',2,'context'),q('What decorated the blouse’s collar?','a gathered strip of white cloth','a rough stone','a rubber eraser','白色褶边装饰了衬衫衣领。',3,'context'),q('Which use of ruffle means “make untidy”?','The wind ruffled the lake.','The question ruffled the mayor.','A ruffle decorated the collar.','第一句中的 ruffle 指把平滑表面弄皱。',1,'meaning')]);
P('rug','Rug is probably of Scandinavian origin, related to a shaggy or coarse covering; it means a small carpet or a thick blanket for covering the legs.',[C('rug.s1','小地毯','A small rug beside the front door caught the sand that visitors tracked in from the beach.','前门旁的小地毯接住了访客从海滩带进来的沙子。','A small rug beside the door / caught the sand / from visitors’ shoes.','rug.s1 指铺在地板一部分的小块地毯。','门口地毯接住鞋底沙粒。'),C('rug.s2','厚毛毯；膝毯','The passenger pulled a wool rug over her knees during the chilly overnight train ride.','寒冷的夜间火车旅程中，乘客把一条羊毛厚毯盖在膝上。','The passenger pulled a wool rug / over her knees / during the chilly ride.','rug.s2 可指盖腿保暖的厚毯子。','乘客用毛毯盖住膝盖。')],M('The passenger used a rug over her knees by spreading a thin paper map across them for warmth.','The passenger used a thick wool rug over her knees to stay warm.','纸地图不能像厚毯子一样保暖。','meaning'),[q('What did the small rug catch?','sand from visitors’ shoes','water from the roughage','a chess piece','门口的小地毯接住了访客鞋底带来的沙子。',1,'context'),q('What did the passenger pull over her knees?','a wool rug','a small carpet for the doorway','a white ruffle','乘客把一条羊毛厚毯盖在膝上。',2,'context'),q('What does rug mean in the doorway example?','a small floor covering','a thick blanket for legs','a rough surface','门口语境中的 rug 指小地毯。',1,'meaning'),q('What does rug mean in the train example?','a thick covering used to keep the legs warm','a carpet used to catch sand','a small badge for an award','火车上盖在腿上的 rug 指厚毛毯。',2,'meaning')]);
P('rugby','Rugby is named after Rugby School in England, where the form of football associated with the school was developed; it is played by carrying, passing, or kicking an oval ball.',C('rugby.s1','橄榄球','The rugby team carried the oval ball over the try line after a fast pass opened a gap in the defense.','一次快速传球撕开防线后，橄榄球队抱着椭圆球冲过达阵线。','The rugby team carried the oval ball / over the try line / after a fast pass.','rugby 指两队通过持球、传球或踢球争取得分的运动。','队员持球冲过达阵线得分。'),M('The rugby team scored by placing a round basketball through a high hoop with no running or passing.','The rugby team scored by carrying the oval ball over the try line.','通过高篮筐投球得分是篮球规则，不是橄榄球。','meaning'),[q('What shape was the ball?','oval','perfectly round','a flat square','橄榄球队使用椭圆球。',1,'context'),q('How did the team score?','carried the ball over the try line','put the ball through a high hoop','rolled a rugby ball into a chess square','队员抱球冲过达阵线得分。',1,'context'),q('What is rugby?','a team game involving carrying, passing, or kicking an oval ball','a race in which runners carry a ruler','a game played only with a round basketball','rugby 是围绕椭圆球进行的团队运动。',1,'meaning'),q('Where did the sport’s name come from?','Rugby School in England','a Roman word for a stomach chamber','a Latin word for a rule','该运动以英国拉格比学校命名。',1,'word-formation')]);
P('rugged','Rugged is recorded for rough, uneven ground; its deeper formation is uncertain. It describes rocky land or a strong, hardy person/harsh conditions.',[C('rugged.s1','崎岖不平的；多岩石的','The hikers followed a rugged trail across loose stones and steep ridges to reach the summit.','徒步者沿着碎石遍布、山脊陡峭的崎岖小路登顶。','The hikers followed a rugged trail / across loose stones / and steep ridges.','rugged.s1 指地面粗糙、不平且多岩石。','山路崎岖多石。'),C('rugged.s2','粗犷强健的；严酷的','The rugged sailor stayed healthy through a harsh winter at sea and repaired the deck in freezing winds.','这名强健粗犷的水手在海上严冬中保持健康，还在寒风中修理甲板。','The rugged sailor stayed healthy / through a harsh winter / at sea.','rugged.s2 可形容经得住艰苦生活的人，也可指严酷条件。','水手在严寒环境中仍强健。')],M('The trail was rugged because it was perfectly smooth, flat, and covered with soft grass.','The trail was rugged because it was rocky, uneven, and steep.','平坦柔软的路面不是崎岖多石。','meaning'),[q('What made the trail rugged?','loose stones and steep ridges','a smooth carpet and a low ceiling','a circular island and a traffic rule','山路碎石遍布，山脊陡峭。',1,'context'),q('What did the rugged sailor do during the winter?','stayed healthy and repaired the deck in freezing winds','left the boat at the first cold gust','rounded a road junction','水手在严冬仍保持健康并修理甲板。',2,'context'),q('What does rugged mean about the trail?','rocky and uneven','healthy and resilient','carefully scheduled','rugged trail 指崎岖不平的山路。',1,'meaning'),q('What does rugged mean about the sailor?','strong and hardy despite hardship','rough ground underfoot','a low continuous sound','rugged sailor 指能经受艰苦生活的强健水手。',2,'meaning')]);
P('ruin','Ruin comes from Latin ruina, from ruere (“fall”), through French; it can mean damage completely, make a person or business bankrupt, or name destroyed remains/a state of destruction.',[C('ruin.s1','毁坏；糟蹋','A leaking pipe could ruin the archive if the staff did not move the paper records to a dry room.','如果工作人员不把纸质档案转移到干燥房间，漏水管道可能会毁掉档案。','A leaking pipe could ruin the archive / if staff did not move / the records.','ruin.s1 作动词，指彻底损坏某物，使之无法使用或享受。','漏水会损坏纸质档案。'),C('ruin.s2','使破产；使沦落','The failed investment nearly ruined the family when it erased their savings and left them with large debts.','投资失败几乎使这个家庭破产，不仅耗尽积蓄还留下巨额债务。','The failed investment nearly ruined the family / by erasing savings / and creating debt.','ruin.s2 指使人或企业失去所有钱财。','投资亏损使家庭陷入债务。'),C('ruin.s3','废墟；毁灭','The castle ruin stood above the valley, its broken walls visible from the river path.','城堡废墟矗立在山谷上方，从河边小路上就能看见破损的墙壁。','The castle ruin stood above the valley / its broken walls / visible from the path.','ruin.s3 作名词，指被毁建筑的遗迹或被毁状态。','城堡只剩下残垣断壁。')],M('The leaking pipe ruined the archive by keeping all the paper records dry and perfectly intact.','The leaking pipe ruined the archive by soaking the documents until they could no longer be used.','保持档案干燥完好不是毁坏档案。','meaning'),[q('What could the leaking pipe ruin?','the archive’s paper records','the castle’s traffic route','the family’s rugby game','漏水管道可能损坏纸质档案。',1,'context'),q('How did the failed investment nearly ruin the family?','it erased their savings and left large debts','it gave them a royal reward','it built a rugged trail','投资失败耗尽家庭积蓄并留下债务。',2,'context'),q('What stood above the valley?','the castle ruin','a new rubber factory','a smooth rowing boat','山谷上方矗立着城堡废墟。',3,'context'),q('What does ruin mean in “ruin the archive”?','damage it completely','make a person bankrupt','the remains of a building','这里 ruin 是动词，指彻底损坏档案。',1,'meaning')]);
P('ruinous','Ruinous is formed from ruin and -ous; it can describe destructive damage or a cost so high that it leads to debt or failure.',[C('ruinous.s1','破坏性的','The ruinous wildfire destroyed the hillside forest and left the nearby village without power.','毁灭性的野火烧毁了山坡森林，还使附近村庄断电。','The ruinous wildfire destroyed the forest / and left the village / without power.','ruinous.s1 指造成严重破坏或毁灭的。','野火严重破坏森林和村庄供电。'),C('ruinous.s2','耗尽钱财的','The company abandoned the ruinous contract after the repair costs rose far beyond its budget.','维修费用远超预算后，公司放弃了这份会导致财务失败的合同。','The company abandoned the ruinous contract / after repair costs / exceeded its budget.','ruinous.s2 指成本高到造成债务或失败的。','高昂成本威胁公司财务。')],M('The company called the contract ruinous even though it cost nothing and produced a large profit.','The company called the contract ruinous because repair costs far exceeded its budget.','不花钱且盈利的合同不是耗尽钱财的。','meaning'),[q('What did the ruinous wildfire do?','destroyed the hillside forest and cut village power','created a new route to the summit','repaired the archive roof','野火烧毁森林并使村庄断电。',1,'context'),q('Why did the company abandon the contract?','repair costs exceeded its budget','it produced a large profit','the workers followed the rota','维修费用过高使合同变得耗尽钱财。',2,'context'),q('What does ruinous mean about the wildfire?','causing severe destruction','costing almost nothing','making the village feel optimistic','ruinous wildfire 指破坏性极强的野火。',1,'meaning'),q('What does ruinous mean about the contract?','so costly it risks debt or failure','likely to be praised by a reviewer','rough but easy to climb','ruinous contract 指成本高到可能导致债务或失败。',2,'meaning')]);
P('ruins','Ruins is the plural of ruin; it means the broken remains of an old building or town that still stand after destruction.',C('ruins.s1','废墟；遗迹（复数）','Visitors walked carefully among the ruins of the old fort, where only the stone arch and outer walls remained.','游客小心地在古堡遗址间行走，那里只剩下石拱门和外墙。','Visitors walked among the ruins / where only the arch / and outer walls remained.','ruins 指受损建筑或城镇仍然留存的破碎部分。','古堡毁坏后留下部分墙体。'),M('Visitors walked among the ruins of the fort even though it was newly built and every wall remained perfect.','Visitors walked among the broken walls and arch that remained from the old fort.','完好如新的建筑不属于废墟。','meaning'),[q('What remained of the old fort?','the stone arch and outer walls','a whole new palace','a rugby field','古堡只剩石拱门和外墙。',1,'context'),q('How did visitors move through the ruins?','carefully','at full speed while playing rugby','by rowing a boat','游客小心地在遗址间行走。',1,'context'),q('What are ruins?','broken remains of old buildings','newly built rooms','a schedule for museum staff','ruins 指旧建筑毁坏后留下的残迹。',1,'meaning'),q('Which site contains ruins?','a damaged fort with only parts of its walls standing','a fully intact newly opened house','a rugged hill with no buildings','只有部分墙体还立着的古堡属于 ruins。',1,'context')]);
P('rule','Rule comes from Latin regula, “straightedge or rule,” through French; it can mean a regulation, govern a country, or decide officially as a judge.',[C('rule.s1','规则；规章','The library rule requires visitors to silence their phones before entering the reading room.','图书馆规定，访客进入阅览室前必须将手机调成静音。','The library rule requires visitors / to silence phones / before entering.','rule.s1 指必须或不得做某事的正式规定。','访客需遵守图书馆规则。'),C('rule.s2','统治；支配','The dynasty ruled the region for nearly two centuries before the republic was established.','共和国建立前，这个王朝统治该地区近两个世纪。','The dynasty ruled the region / for nearly two centuries / before the republic.','rule.s2 作动词，指对国家或群体拥有正式权力。','王朝长期统治该地区。'),C('rule.s3','裁定；裁决','The judge ruled that the company had to repair the damaged bridge before reopening it.','法官裁定，公司必须修好受损桥梁后才能重新开放。','The judge ruled / that the company had to repair / the bridge before reopening.','rule.s3 指法官等权威人士正式作出决定。','法官作出维修裁决。')],M('The library rule required visitors to use loud speakers throughout the quiet reading room.','The library rule required visitors to silence their phones in the reading room.','要求在安静阅览室使用扬声器与图书馆规则相悖。','meaning'),[q('What must visitors do before entering the reading room?','silence their phones','repair the bridge','rule the region','图书馆规则要求访客先将手机调成静音。',1,'context'),q('How long did the dynasty rule the region?','nearly two centuries','one afternoon','until the bridge collapsed','王朝统治该地区近两个世纪。',2,'context'),q('What did the judge rule?','the company had to repair the bridge before reopening','the library had to close forever','the dynasty could rule again','法官裁定公司必须修好桥梁才能重新开放。',3,'context'),q('What does rule mean in “the dynasty ruled the region”?','governed it','stated a library regulation','decided a legal case','此处 rule 是“统治”。',2,'meaning')]);
P('rule out','Rule out combines rule and out; it means decide that an option or possibility is impossible or choose not to consider it.',C('rule out.s1','排除；不考虑','The mechanic ruled out a dead battery after testing it and finding that it held a full charge.','技师检测后发现电池电量充足，于是排除了电池没电这一可能。','The mechanic ruled out a dead battery / after testing it / and finding a full charge.','rule out 指确认某种可能不成立，或决定不予考虑。','测试结果排除了电池没电。'),M('The mechanic ruled out a dead battery even though the test showed it was completely discharged and unable to start the car.','The mechanic ruled out a dead battery because the test showed it was fully charged.','电池完全没电时不能据此排除电池故障。','meaning'),[q('What did the mechanic rule out?','a dead battery','a full fuel tank','a broken ruler','技师发现电池电量充足，排除了电池没电。',1,'context'),q('Why was a dead battery ruled out?','it held a full charge','it was completely discharged','the mechanic lost the test result','检测发现电池充足，因此排除了电池没电。',1,'context'),q('What does rule out mean?','decide an option is impossible or not worth considering','make a formal court judgment','govern a region','rule out 指排除某种可能或不予考虑。',1,'meaning'),q('Which diagnosis has been ruled out?','the battery is dead, after a full-charge test','the bridge needs a safety inspection','the company will reopen tomorrow','电池满电后，“电池没电”这一诊断被排除。',1,'context')]);
P('ruler','Ruler is formed from rule and -er; it can mean a person who governs people or a straight tool used to measure or draw lines.',[C('ruler.s1','统治者；君主','The ruler issued a decree that opened the mountain road to merchants from neighboring towns.','统治者颁布法令，允许邻镇商人使用山路。','The ruler issued a decree / opening the mountain road / to neighboring merchants.','ruler.s1 指统治国家或人民的人或群体。','统治者颁布通行法令。'),C('ruler.s2','直尺；尺子','Use a ruler to draw a straight line between the two marks on the map.','用直尺在地图上的两个标记之间画一条直线。','Use a ruler to draw a straight line / between the two marks / on the map.','ruler.s2 指用于测量或画直线的直条工具。','直尺连接地图上的两点。')],M('The student used a ruler to draw a straight line by bending a piece of string around the page.','The student used a ruler, a straight measuring tool, to draw the line.','弯曲的绳子不能提供直尺的直边。','meaning'),[q('What did the ruler’s decree allow?','merchants to use the mountain road','the company to avoid repairing the bridge','the library to use loud phones','统治者颁布法令允许邻镇商人使用山路。',1,'context'),q('What did the student use to draw a straight line?','a straight measuring tool','a piece of curved string','a rugby ball','学生用直尺连接地图上的两个标记。',2,'context'),q('Who is a ruler in the first sentence?','a person governing a region','a tool for measuring a map','a judge deciding a case','第一句中的 ruler 指统治者。',1,'meaning'),q('What does ruler mean in the map instruction?','a straight tool used to measure or draw','a person who governs a country','a regulation in a library','地图指令中的 ruler 指直尺。',2,'meaning')]);
P('rules','Rules is the plural of rule; it means a set of requirements for a game, activity, or organization, or the principles governing language.',[C('rules.s1','规则；规章','The board-game rules say that each player may move one piece per turn.','棋盘游戏规则规定每位玩家每回合只能移动一枚棋子。','The board-game rules say / each player may move / one piece per turn.','rules.s1 指游戏、活动或组织中必须遵守的一系列规定。','规则限制每回合的棋子移动数。'),C('rules.s2','语法规则','The teacher explained the rules of English punctuation before students edited their essays.','学生修改作文前，老师讲解了英语标点的规则。','The teacher explained punctuation rules / before students / edited their essays.','rules.s2 指说明语言中词语和句子如何使用的原则。','老师讲解英语标点用法。')],M('The board-game rules allowed every player to move as many pieces as they wanted during each turn.','The board-game rules limited each player to moving one piece per turn.','规则明确限制每回合只能移动一枚棋子。','meaning'),[q('How many pieces may each player move per turn?','one','as many as desired','none, even on the player’s turn','棋盘规则规定每位玩家每回合可移动一枚棋子。',1,'context'),q('What did the teacher explain before essay editing?','English punctuation rules','the rugby rules','the route to the mountain','老师在学生改作文前讲解了英语标点规则。',2,'context'),q('What do game rules do?','set requirements players must follow','explain how words are spelled','govern an entire country','游戏 rules 规定玩家必须遵守的要求。',1,'meaning'),q('What do language rules describe?','how words and sentences may be used','how players move a chess rook','how a judge rules on a case','语言 rules 说明词语和句子的使用方式。',2,'meaning')]);
P('ruling','Ruling comes from rule and -ing; it can mean an official decision, or describe the group currently governing or the most widely accepted view.',[C('ruling.s1','裁决；裁定','The court’s ruling required the factory to reduce its noise before the night shift began.','法院裁决要求工厂在夜班开始前降低噪声。','The court’s ruling required / the factory to reduce noise / before night shift.','ruling.s1 指法官或法院对事项作出的正式决定。','法院作出降噪裁定。'),C('ruling.s2','统治的；主导的','The ruling party introduced a new transport policy after winning the national election.','执政党赢得全国选举后提出了新的交通政策。','The ruling party introduced a policy / after winning / the national election.','ruling.s2 指当前掌权的，也可指最常见或被普遍接受的。','执政党提出政策。')],M('The court’s ruling required the factory to make more noise during the night shift and ignore nearby residents.','The court’s ruling required the factory to reduce noise before night shift.','法院裁定降低噪声，而非制造更大噪声。','meaning'),[q('What did the court’s ruling require?','reduce factory noise before night shift','make noise louder at night','cancel the national election','法院裁决要求工厂夜班前降低噪声。',1,'context'),q('What did the ruling party do after the election?','introduced a transport policy','left office before voting','ruled out the election','执政党在赢得选举后提出了交通政策。',2,'context'),q('What is a ruling in the court example?','an official decision','the group currently governing','the most common view','法院语境中的 ruling 指正式裁定。',1,'meaning'),q('What does ruling mean in “the ruling party”?','currently governing','an official court decision','a noisy sound','ruling party 指当前执政的政党。',2,'meaning')]);
P('rumble','Rumble is probably echoic in origin, imitating a low continuous sound; it can name such a sound or mean make it.',[C('rumble.s1','隆隆声；轰隆声','A distant rumble of thunder rolled over the valley before the first drops of rain fell.','第一滴雨落下前，远处的雷声隆隆掠过山谷。','A distant rumble of thunder rolled / over the valley / before rain began.','rumble.s1 指持续一段时间的低沉响声。','远处传来持续雷声。'),C('rumble.s2','发出隆隆声；轰鸣','The old truck rumbled along the gravel road as its engine shook the windows.','旧卡车沿碎石路轰隆驶过，发动机震得窗户发颤。','The old truck rumbled along the gravel road / as its engine / shook the windows.','rumble.s2 作动词，指发出低沉而持续的响声。','卡车发动机持续轰鸣。')],M('The truck rumbled along the road in complete silence, producing no sound at all.','The truck rumbled along the road with a low continuous engine sound.','完全无声不符合 rumble 的轰鸣义。','meaning'),[q('What rolled over the valley before rain?','a low rumble of thunder','a smooth rugby ball','a ruling party','下雨前远处雷声隆隆掠过山谷。',1,'context'),q('What made the old truck rumble?','its engine shook the windows','the court issued a ruling','the road was a roundabout','发动机震动窗户，卡车沿碎石路轰鸣。',2,'context'),q('What does rumble mean as a noun?','a low sound continuing for some time','a complete court decision','a straight measuring line','rumble 作名词指低沉持续的声音。',1,'meaning'),q('What does rumble mean as a verb?','make a low continuous sound','make a final ruling','look for an item messily','动词 rumble 指发出低沉持续的声音。',2,'meaning')]);
P('rumen','Rumen comes from Latin rumen, “throat or paunch”; it is the large first chamber of a ruminant’s stomach where microbes ferment plant food.',C('rumen.s1','瘤胃','Microbes in the cow’s rumen break down tough plant fibers before the animal digests the food further.','牛瘤胃中的微生物先分解坚韧的植物纤维，然后动物再继续消化。','Microbes in the cow’s rumen break down / tough plant fibers / before later digestion.','rumen 指反刍动物胃中最前面、负责微生物发酵的腔室。','瘤胃微生物分解植物纤维。'),M('The cow’s rumen was the chamber where its lungs exchanged oxygen and carbon dioxide.','The cow’s rumen was the first stomach chamber where microbes fermented plant food.','肺负责气体交换，rumen 是胃的一部分。','meaning'),[q('What do microbes in the cow’s rumen break down?','tough plant fibers','oxygen in the lungs','a rugby ball','瘤胃微生物分解坚韧的植物纤维。',1,'context'),q('Which animal organ is the rumen part of?','the stomach of a ruminant','the lung of a ruler','the heart of a rhinoceros','rumen 是反刍动物胃中的一个腔室。',1,'meaning'),q('What happens in the rumen before later digestion?','microbes ferment plant food','the animal’s lungs exchange gases','the animal measures a route','瘤胃中的微生物先发酵植物食物。',1,'context'),q('Which Latin word is related to rumen?','rumen, “throat or paunch”','regula, “straightedge”','rota, “wheel”','rumen 来自拉丁语 rumen，意为喉部或腹腔。',1,'word-formation')]);
P('ruminant','Ruminant comes from Latin ruminare, “chew the cud”; it names a hoofed cud-chewing mammal and can describe reflective thought.',[C('ruminant.s1','反刍动物','A deer is a ruminant: it chews cud and digests leaves in a specialized stomach.','鹿是反刍动物：它会反刍，并在特化的胃中消化树叶。','A deer is a ruminant / that chews cud / in a specialized stomach.','ruminant.s1 指具有特化胃、会反刍植物的有蹄哺乳动物。','鹿通过反刍消化植物。'),C('ruminant.s2','反刍的；沉思的','After the meeting, she took a ruminant walk by the river, thinking slowly about the difficult choice.','会议结束后，她沿河散步，沉思那个艰难选择。','She took a ruminant walk / thinking slowly / about the difficult choice.','ruminant.s2 可形容人缓慢、深入地反复思考。','散步时她认真考虑选择。')],M('A deer is a ruminant because it has no specialized stomach and never chews its food again.','A deer is a ruminant because it digests plants in a specialized stomach and chews cud.','不具备特化胃且不反刍，不能说明鹿是反刍动物。','meaning'),[q('What does the deer do as a ruminant?','chews cud and digests leaves','runs away from a predator','measures its route with a ruler','鹿会反刍，并在特化胃中消化植物。',1,'context'),q('What was the woman thinking about on her ruminant walk?','a difficult choice','the rugby score only','a court’s ruling on noise','她沿河散步时沉思一个艰难选择。',2,'context'),q('What is a ruminant animal?','a hoofed mammal that chews cud','a bird that nests in colonies','a mammal with no stomach','ruminant 指会反刍的有蹄哺乳动物。',1,'meaning'),q('What does ruminant mean about the walk?','reflective and thoughtful','related to a cud-chewing animal only','loud and continuous','ruminant walk 描写沉思的散步。',2,'meaning')]);
P('ruminate','Ruminate comes from Latin ruminari, “chew the cud”; it can mean think deeply for a long time or, of cattle and similar animals, bring food back up and chew it again.',[C('ruminate.s1','沉思；冥想','He continued to ruminate on the offer over the weekend before deciding whether to change jobs.','整个周末他都在认真思考这份邀约，之后才决定是否换工作。','He continued to ruminate on the offer / over the weekend / before deciding.','ruminate.s1 指安静而长时间地深入思考。','他反复考虑是否换工作。'),C('ruminate.s2','（牛羊）反刍','The sheep ruminated in the shade, bringing up grass from its first stomach chamber and chewing it again.','羊在树荫下反刍，把第一胃室中的草食返回口中再次咀嚼。','The sheep ruminated in the shade / bringing up grass / to chew again.','ruminate.s2 指反刍动物把吞下的食物返回口中重新咀嚼。','绵羊再次咀嚼胃中的草。')],M('He ruminated on the job offer by making an instant decision without considering it at all.','He ruminated on the job offer by thinking about it carefully over the weekend.','毫不考虑便立刻决定，不属于长时间沉思。','meaning'),[q('How long did he ruminate on the job offer?','over the weekend','for one second without thinking','until the sheep finished grazing','他整个周末都在认真考虑工作邀约。',1,'context'),q('What did the sheep bring up to chew again?','grass from its first stomach chamber','a rugby ball','a wooden ruler','绵羊把胃中的草返回口中再次咀嚼。',2,'context'),q('What does ruminate mean in the job example?','think deeply for a long time','chew swallowed food again','run quickly away','这里 ruminate 指长时间深入思考。',1,'meaning'),q('What does ruminate mean about the sheep?','bring food back up and chew it again','think about a job offer','measure a line','绵羊 ruminated 指反刍食物。',2,'meaning')]);
P('rummage','Rummage has an uncertain deeper origin; it means search hurriedly and untidily by moving other things around.',C('rummage.s1','翻找','She rummaged through the desk drawer for the missing key, shifting pens and old receipts aside.','她在书桌抽屉里翻找丢失的钥匙，把钢笔和旧收据拨到一旁。','She rummaged through the drawer / for the missing key / moving items aside.','rummage 指急忙而杂乱地翻动物品寻找东西。','她翻动抽屉里的杂物找钥匙。'),M('She rummaged through the drawer by leaving every item in place and never searching for anything.','She rummaged through the drawer by moving the pens and receipts aside to find the key.','不翻动或搜寻物品不是 rummage。','meaning'),[q('What was she searching for?','a missing key','a rugby uniform','the ruling party','她翻找抽屉是为了找丢失的钥匙。',1,'context'),q('What did she move aside while rummaging?','pens and old receipts','the desk itself','the room’s walls','她把钢笔和旧收据拨开寻找钥匙。',1,'context'),q('What does rummage mean?','search by moving things around untidily','measure something with a straight edge','chew food a second time','rummage 指翻动杂物进行搜寻。',1,'meaning'),q('Which action is rummaging?','turning over a bag’s contents to find a ticket','looking at the top item without touching anything','following a marked route','翻动包中物品找车票属于 rummage。',1,'context')]);
P('rumor','Rumor comes from Latin rumor, “noise or report,” through French; it can mean unverified news people repeat or the act of reporting something as a rumor.',[C('rumor.s1','谣言；传闻','A rumor that the factory would close spread through town, although the company had made no announcement.','工厂即将关闭的传闻在镇上流传，尽管公司并未发布公告。','A rumor about the factory closing spread / although the company / made no announcement.','rumor.s1 指被人传播但可能不真实的消息。','工厂关闭的说法尚未证实。'),C('rumor.s2','谣传；据说','Neighbors rumor that the old theater will reopen, but the owner has not confirmed any plans.','邻居们谣传老剧院将重新开放，但业主还未确认计划。','Neighbors rumor that the theater will reopen / but the owner / has not confirmed plans.','rumor.s2 作动词，指把未经证实的消息当传闻讲述。','邻居在传播未经确认的消息。')],M('The factory-closing rumor was an official announcement signed by the company and confirmed by its owner.','The factory-closing rumor was unverified news that the company had not announced.','正式签署并确认的公告不是未经证实的传闻。','meaning'),[q('What did the company say about the factory rumor?','it had made no announcement','it had signed an official closure notice','it had already reopened the theater','公司没有发布工厂关闭公告，因此消息仍是传闻。',1,'context'),q('Who has not confirmed plans to reopen the old theater?','the owner','the neighbors','the ruling party','剧院业主尚未确认重新开放的计划。',2,'context'),q('What is a rumor?','news people repeat although it may be false','a confirmed public decree','a regular work schedule','rumor 指可能不真实却被传播的消息。',1,'meaning'),q('What does rumor mean as a verb?','report something as an unverified story','announce something officially','search through a drawer','rumor 作动词指传播未经证实的传闻。',2,'meaning')]);
P('run','Run comes from Old English rinnan/iernan; it can mean move quickly on foot, manage a business or machine, or name a race/regular trip/period.',[C('run.s1','跑；奔跑','The children ran across the field when the school bell rang for lunch.','午餐铃响后，孩子们跑过操场。','The children ran across the field / when the lunch bell / rang.','run.s1 指用双脚快速移动。','孩子们听到铃声后跑向餐厅。'),C('run.s2','经营；管理；运转','She runs a small bakery that opens before dawn and delivers bread to nearby schools.','她经营一家小面包店，天亮前开门并向附近学校送面包。','She runs a small bakery / that opens before dawn / and delivers bread.','run.s2 可指管理企业或使机器运作。','店主经营面包店并安排配送。'),C('run.s3','跑；行程；一连串；得分','The pharmacy’s morning run takes its driver to four clinics before noon.','药房司机上午的固定配送行程会在中午前前往四家诊所。','The pharmacy’s morning run takes the driver / to four clinics / before noon.','run.s3 作名词可指一次跑步、固定行程或一段连续活动。','司机按固定行程配送药品。')],M('The children ran across the field by remaining seated and never moving their feet.','The children ran across the field by moving quickly on foot.','坐着不动不是跑步。','meaning'),[q('What did the children do when the lunch bell rang?','ran across the field','managed a bakery','followed the morning delivery route','孩子们听到午餐铃后跑过操场。',1,'context'),q('What does the woman run?','a small bakery','a rugby team’s final match','a pharmacy delivery van only','她经营一家向学校送面包的小店。',2,'context'),q('Where does the pharmacy’s morning run go?','to four clinics','to the rugby field','to one bakery only','药房上午的固定配送行程会去四家诊所。',3,'context'),q('What does run mean in “she runs a bakery”?','manage or operate a business','move quickly on foot','a regular delivery trip','这里 run 是经营、管理的意思。',2,'meaning')]);
P('run away','Run away combines run and away; it means leave a place quickly by running, especially because of danger or fear.',C('run away.s1','跑开；逃跑','When the loose dog barked and charged, the frightened child ran away toward the open shop.','松脱的狗吠叫着冲过来时，受惊的孩子朝着开门的商店逃去。','The frightened child ran away / toward the open shop / when the dog charged.','run away 指因危险或害怕而跑离某处。','孩子为躲避冲来的狗而逃跑。'),M('The frightened child ran away from the charging dog by walking slowly toward it and staying beside it.','The frightened child ran away from the charging dog by sprinting toward a safe place.','朝危险靠近并停留不是逃跑。','meaning'),[q('What made the child run away?','a loose dog charged toward them','the school bell rang for lunch','a delivery driver reached a clinic','孩子因狗冲过来而逃跑。',1,'context'),q('Where did the child run?','toward an open shop','toward the charging dog','into a locked room with no exit','孩子朝开门的商店逃去。',1,'context'),q('What does run away mean?','leave quickly by running, often from danger','manage a small business','take a regular delivery trip','run away 指快速逃离，常因害怕或危险。',1,'meaning'),q('Which action is running away?','sprinting from a fire toward an exit','walking toward a harmless dog to greet it','running a bakery before dawn','从火场冲向出口属于 run away。',1,'context')]);
P('run fast','Run fast combines run and fast; it means move quickly on foot.',C('run fast.s1','跑得快；飞快地跑','The sprinter trained on the track each morning to run fast during the regional final.','短跑运动员每天早晨在跑道训练，以便在地区决赛中跑得快。','The sprinter trained each morning / to run fast / in the regional final.','run fast 指以较高速度用双脚奔跑。','运动员通过训练提高跑步速度。'),M('The sprinter ran fast by standing still at the starting line for the entire race.','The sprinter ran fast by moving quickly along the track.','站着不动不能算跑得快。','meaning'),[q('Where did the sprinter train?','on the track','in the pharmacy','inside the old theater','短跑运动员每天在跑道上训练。',1,'context'),q('Why did the sprinter train?','to move quickly in the regional final','to run a bakery','to escape a charging dog','运动员训练是为了在决赛中跑得快。',1,'context'),q('What does run fast mean?','move quickly on foot','manage a business efficiently','leave a place because of danger','run fast 指快速奔跑。',1,'meaning'),q('Which person can run fast?','a sprinter accelerating down the track','a child sitting without moving','a shop owner opening a bakery','沿跑道加速的短跑选手可以 run fast。',1,'context')]);
P('run into','Run into combines run and into; it means meet someone by chance or begin to experience a difficulty or problem.',[C('run into.s1','偶遇；碰见','I ran into my former coach at the station while waiting for the northbound train.','我在车站等北行列车时偶遇了以前的教练。','I ran into my former coach / at the station / while waiting for a train.','run into.s1 指意外遇见某人或看到某物。','在车站偶遇旧教练。'),C('run into.s2','遭遇；碰到问题','The renovation ran into delays when workers discovered hidden water damage behind the wall.','工人发现墙后有隐藏的水渍损坏后，翻修工程遇到了延误。','The renovation ran into delays / when workers found / hidden water damage.','run into.s2 指开始经历困难、障碍或问题。','隐藏的水渍导致工程延误。')],M('I ran into my former coach at the station by arranging an appointment with him weeks earlier.','I ran into my former coach unexpectedly while waiting for the train.','提前安排会面不是偶然碰见。','meaning'),[q('Where did the speaker run into the former coach?','at the station','on the rugby field','in the ruined castle','说话者在车站等车时偶遇了以前的教练。',1,'context'),q('What caused the renovation to run into delays?','hidden water damage behind the wall','a ruler measuring the room','the crew running fast','墙后隐藏的水渍损坏使翻修工程延误。',2,'context'),q('What does run into mean in the station example?','meet by chance','begin to experience a problem','move quickly on foot','车站句中的 run into 指偶然碰见。',1,'meaning'),q('What does run into mean in the renovation example?','encounter or experience a difficulty','meet a former coach unexpectedly','manage a business','工程句中的 run into 指遭遇问题。',2,'meaning')]);
})();
